var e=JSON.parse('[[1301,"Методы `bind`, `call` и `apply` позволяют изменять контекст выполнения функции:\\n\\n- bind создает новую функцию с привязанным контекстом.\\n\\n- call вызывает функцию немедленно, передавая ей контекст и аргументы.\\n\\n- apply похож на `call`, но аргументы передаются в виде массива.","В JavaScript контекст исполнения функции — это объект, на который ссылается ключевое слово `this`. Методы `bind`, `call` и `apply` помогают управлять этим контекстом:\\n\\n- bind:\\n\\n- Метод `bind` создает новую функцию, которая при вызове всегда будет использовать заданный контекст. Это удобно, если нужно передать функцию с определённым контекстом.\\n\\n- Пример:\\n\\n- call:\\n\\n- Метод `call` вызывает функцию немедленно с переданным контекстом и аргументами. Это позволяет вызвать функцию с произвольным контекстом.\\n\\n- Пример:\\n\\n- apply:\\n\\n- Метод `apply` работает аналогично `call`, но аргументы передаются в виде массива.\\n\\n- Пример:\\n\\nВывод:\\nМетоды `bind`, `call` и `apply` важны для управления контекстом в JavaScript. Они позволяют вызывать функции с нужным объектом, что особенно полезно при работе с асинхронным кодом и событиями.","function greet() {\\n  console.log(`Hello, ${this.name}`);\\n}\\nconst person = { name: \'Alice\' };\\nconst greetPerson = greet.bind(person);\\ngreetPerson();  // \\"Hello, Alice\\"\\n\\nfunction greet(age) {\\n  console.log(`${this.name} is ${age} years old`);\\n}\\nconst person = { name: \'Bob\' };\\ngreet.call(person, 30);  // \\"Bob is 30 years old\\"\\n\\nfunction sum(a, b) {\\n  console.log(a + b);\\n}\\nsum.apply(null, [3, 4]);  // 7"],[1302,"Функция `reduce` используется для последовательной обработки элементов массива с сохранением промежуточного результата. Она принимает функцию обратного вызова, которая получает два аргумента — аккумулятор и текущий элемент массива.","Метод `reduce` позволяет пройти по всем элементам массива и свести их к одному значению. Этот метод полезен для агрегации данных, например, для подсчета суммы, поиска максимума или объединения строк.\\n\\n- Синтаксис:\\n\\n- `accumulator` — это значение, которое сохраняет промежуточные результаты.\\n\\n- `currentValue` — это текущий элемент массива.\\n\\n- `initialValue` — начальное значение аккумулятора (опционально).\\n\\n- Пример с суммой:\\n\\n- Пример с поиском максимального значения:\\n\\nВывод:\\n`reduce` — это мощный инструмент для агрегации данных в массиве. Он помогает собрать информацию по шагам, что полезно при решении задач вроде подсчета или комбинирования значений.","array.reduce((accumulator, currentValue) => {\\n  // операцию с accumulator и currentValue\\n}, initialValue);\\n\\nconst numbers = [1, 2, 3, 4];\\nconst sum = numbers.reduce((acc, current) => acc + current, 0);\\nconsole.log(sum);  // 10\\n\\nconst numbers = [10, 20, 30, 40];\\nconst max = numbers.reduce((max, current) => (current > max ? current : max), numbers[0]);\\nconsole.log(max);  // 40"],[1303,"Для оптимизации работы с вложенными объектами можно:\\n\\n- Использовать мемоизацию для сохранения промежуточных результатов.\\n\\n- Применять техники ленивой загрузки данных, чтобы загружать только необходимые части.\\n\\n- Использовать `Map` или `Set` для эффективного поиска.","Работа с большими вложенными объектами может быть дорогой с точки зрения производительности, особенно если данные нужно часто изменять или просматривать. Рассмотрим несколько подходов к оптимизации:\\n\\n- Мемоизация:\\n\\n- Мемоизация позволяет сохранять результаты вычислений и использовать их повторно, что уменьшает время выполнения. Применяется в функциях, которые часто вызываются с одинаковыми параметрами.\\n\\n- Пример:\\n\\n- Ленивая загрузка данных (Lazy Loading):\\n\\n- Можно загружать данные по мере необходимости, а не загружать весь объект сразу. Это особенно полезно при работе с данными, которые могут быть не всегда нужны.\\n\\n- Использование `Map` и `Set`:\\n\\n- Когда необходимо работать с большими объемами данных и часто искать или обновлять элементы, лучше использовать структуры данных, такие как `Map` или `Set`, которые обеспечивают быстрый поиск и вставку.\\n\\nВывод:\\nДля оптимизации работы с большими вложенными объектами важно избегать ненужных вычислений и загружать только необходимые данные. Мемоизация и ленивые подходы помогают существенно повысить производительность.","const memoize = (fn) => {\\n  const cache = new Map();\\n  return (...args) => {\\n    const key = JSON.stringify(args);\\n    if (!cache.has(key)) {\\n      cache.set(key, fn(...args));\\n    }\\n    return cache.get(key);\\n  };\\n};"],[1304,"Для улучшения читаемости кода в циклах можно использовать:\\n\\n- Декомпозицию сложных операций в отдельные функции.\\n\\n- Местное использование переменных для промежуточных результатов.\\n\\n- Использование методов массивов, таких как `map`, `filter` и `reduce`, вместо обычных циклов.","Когда работаешь с большими и сложными структурами данных, циклы могут становиться трудными для восприятия. Вот несколько способов улучшить читаемость кода:\\n\\n- Декомпозиция:\\n\\n- Разбивайте сложные операции, которые выполняются внутри цикла, на отдельные функции. Это не только улучшает читаемость, но и помогает повторно использовать код.\\n\\n- Пример:\\n\\n- Местное использование переменных:\\n\\n- Используйте понятные переменные для хранения промежуточных результатов, что помогает избежать путаницы и делает код более читаемым.\\n\\n- Пример:\\n\\n- Использование методов массивов:\\n\\n- Вместо стандартных циклов можно использовать методы массивов, такие как `map`, `filter`, `reduce`, которые делают код более декларативным и читаемым.\\n\\n- Пример:\\n\\nВывод:\\nДля повышения читаемости кода в циклах важно использовать принципы декомпозиции, понятные имена переменных и применять встроенные методы массивов, чтобы сделать код более понятным и поддерживаемым.","// Плохой вариант\\nfor (let i = 0; i < data.length; i++) {\\n  if (data[i].isActive) {\\n    processItem(data[i]);\\n  }\\n}\\n\\n// Хороший вариант\\nconst processActiveItems = (item) => {\\n  if (item.isActive) {\\n    processItem(item);\\n  }\\n};\\n\\nfor (let i = 0; i < data.length; i++) {\\n  processActiveItems(data[i]);\\n}\\n\\n// Местное использование переменной для хранения промежуточных значений\\nconst result = processData(item);\\nif (result.isValid) {\\n  doSomething(result);\\n}\\n\\nconst activeItems = data.filter(item => item.isActive);\\nactiveItems.forEach(item => processItem(item));"],[1305,"Для конвертации JSON в CSV можно использовать следующие шаги:\\n\\n- Преобразовать JSON в массив объектов.\\n\\n- Извлечь ключи объектов как заголовки.\\n\\n- Преобразовать данные в строку CSV, разделенную запятыми.","JSON и CSV — два популярных формата для представления данных. Чтобы конвертировать данные из JSON в CSV, нужно выполнить несколько шагов:\\n\\n- Преобразование JSON в массив объектов:\\n\\n- JSON часто представлен как массив объектов. Важно правильно разобрать этот массив и работать с ним.\\n\\n- Пример:\\n\\n- Извлечение ключей объектов для заголовков CSV:\\n\\n- Ключи объектов становятся заголовками столбцов в CSV.\\n\\n- Пример:\\n\\n- Преобразование данных в CSV-строку:\\n\\n- Для каждого объекта в JSON можно создать строку CSV, разделяя значения запятыми.\\n\\n- Пример:\\n\\n- Результат:\\n\\nВывод:\\nПреобразование JSON в CSV — это процесс, включающий извлечение данных и их форматирование в строки с разделителями. Важно правильно работать с заголовками и значениями для получения правильного результата.","const jsonData = [\\n  { \\name\\": \\"Alice\\", \\"age\\": 25 },\\n  { \\name\\": \\"Bob\\", \\"age\\": 30 }\\n];\\n\\nconst headers = Object.keys(jsonData[0]);\\n\\nconst csvRows = [];\\ncsvRows.push(headers.join(\',\')); // Добавляем заголовки\\n\\njsonData.forEach(row => {\\n  csvRows.push(headers.map(header => row[header]).join(\',\'));\\n});\\n\\nconst csvString = csvRows.join(\'\\"\\n\');\\nconsole.log(csvString);\\n\\nname,age\\nAlice,25\\nBob,30"],[1306,"Методы `Object.keys` и `Object.values` позволяют извлекать ключи и значения объекта соответственно:\\n\\n- Object.keys возвращает массив всех ключей объекта.\\n\\n- Object.values возвращает массив всех значений объекта.","Методы `Object.keys` и `Object.values` полезны при работе с объектами, так как позволяют легко получать массивы ключей или значений. Оба метода являются встроенными в JavaScript и не изменяют сам объект.\\n\\n- Object.keys:\\n\\n- Этот метод возвращает массив, содержащий все ключи объекта. Массив включает только перечисляемые свойства объекта.\\n\\n- Пример:\\n\\n- Object.values:\\n\\n- Этот метод возвращает массив, содержащий все значения объекта для соответствующих ключей.\\n\\n- Пример:\\n\\n- Сравнение с другими методами:\\n\\n- Помимо `keys` и `values`, также существует метод `Object.entries`, который возвращает массив пар [ключ, значение].\\n\\n- Пример:\\n\\nВывод:\\nМетоды `Object.keys` и `Object.values` полезны для получения информации о структуре объекта в виде массива. Эти методы делают работу с объектами в JavaScript более удобной и читаемой.","const person = { name: \'Alice\', age: 25 };\\nconst keys = Object.keys(person);\\nconsole.log(keys);  // [\'name\', \'age\']\\n\\nconst person = { name: \'Alice\', age: 25 };\\nconst values = Object.values(person);\\nconsole.log(values);  // [\'Alice\', 25]\\n\\nconst entries = Object.entries(person);\\nconsole.log(entries);  // [[\'name\', \'Alice\'], [\'age\', 25]]"],[1307,"Для работы с Canvas и 2D-графикой используют как нативный Canvas API, так и библиотеки-обёртки. Популярные решения упрощают работу с фигурами, событиями, трансформациями и состоянием сцены. Выбор зависит от сложности сцены, требований к интерактивности и производительности. Для простых задач достаточно чистого Canvas, для сложных — удобнее библиотеки.","Работа с 2D-графикой в браузере может вестись на разных уровнях абстракции. Перед выбором инструмента важно понимать, какую задачу он решает.\\nНативный подход\\nCanvas API — это низкоуровневый интерфейс для рисования пикселей.\\n\\n- Полный контроль над отрисовкой\\n\\n- Максимальная производительность\\n\\n- Вся логика сцены и состояний реализуется вручную\\n\\nИспользуется, когда:\\n\\n- требуется кастомный рендеринг\\n\\n- важна высокая производительность\\n\\n- сцена относительно простая по логике\\n\\nБиблиотеки поверх Canvas\\nЭти решения берут на себя управление сценой, объектами и событиями.\\n\\n- Fabric.js\\n\\n- Объектная модель (фигуры, группы, трансформации)\\n\\n- Удобная работа с SVG\\n\\n- Подходит для редакторов и конструкторов\\n\\n- Konva.js\\n\\n- Слои и сцены\\n\\n- Хорошая интеграция с React\\n\\n- Часто используется для интерактивных интерфейсов\\n\\n- PixiJS\\n\\n- Высокая производительность\\n\\n- Часто применяется в играх\\n\\n- Использует WebGL, но подходит и для 2D\\n\\n- Paper.js\\n\\n- Векторная графика\\n\\n- Удобен для иллюстраций и геометрии\\n\\n- Менее ориентирован на UI-сценарии\\n\\nКраткий вывод\\nДля UI-ориентированных и интерактивных сцен чаще выбирают Fabric.js или Konva.js. Для игр и сложной анимации — PixiJS. Чистый Canvas оправдан, когда нужна максимальная гибкость и контроль.",null],[1308,"SVG и Canvas используют разные модели рендеринга. SVG — декларативный и объектный, Canvas — императивный и пиксельный. При отрисовке SVG в Canvas теряется его структура и интерактивность. Поэтому SVG обычно сначала парсится, а затем «перерисовывается» в Canvas.","SVG и Canvas принципиально отличаются по своей архитектуре, и это напрямую влияет на способ их совместного использования.\\nРазличие моделей рендеринга\\nSVG:\\n\\n- DOM-ориентированный\\n\\n- Каждый элемент — отдельный узел\\n\\n- Сохраняет структуру и иерархию\\n\\nCanvas:\\n\\n- Пиксельный буфер\\n\\n- После отрисовки нет информации об объектах\\n\\n- Нет встроенной структуры сцены\\n\\nЧто происходит при отрисовке SVG в Canvas\\nОбычно процесс выглядит так:\\n\\n- SVG загружается как файл или строка\\n\\n- Он парсится браузером или библиотекой\\n\\n- Элементы SVG преобразуются в команды Canvas\\n\\nВ результате:\\n\\n- SVG становится «плоским» изображением\\n\\n- Исчезают группы, id и семантика\\n\\n- События и стили SVG больше не работают автоматически\\n\\nПрактические последствия\\n\\n- Нельзя напрямую навесить события на элементы SVG\\n\\n- Любые трансформации нужно отслеживать вручную\\n\\n- Изменение одного объекта требует полной или частичной перерисовки сцены\\n\\nКраткий вывод\\nCanvas не умеет работать с SVG как со структурированными объектами. SVG при отрисовке превращается в набор пикселей, поэтому вся логика взаимодействия и состояния должна быть реализована отдельно.",null],[1309,"Fabric.js при импорте SVG преобразует элементы в объекты Canvas. Группы SVG могут быть объединены в `Group`, но иерархия часто упрощается. Слоёв в классическом смысле нет, порядок объектов определяется их позицией в массиве. Управление группами и порядком отрисовки выполняется программно.","Fabric.js использует собственную объектную модель поверх Canvas, которая лишь частично соответствует структуре SVG.\\nИмпорт SVG в Fabric.js\\nПри загрузке SVG:\\n\\n- Каждый SVG-элемент превращается в объект Fabric\\n\\n- `<g>` может быть преобразован в `fabric.Group`\\n\\n- Часть вложенности может быть утеряна или упрощена\\n\\nЭто связано с тем, что Fabric ориентирован на Canvas-рендеринг, а не на DOM-иерархию.\\nРабота с группами\\n`Group` в Fabric.js:\\n\\n- Объединяет несколько объектов\\n\\n- Применяет трансформации ко всей группе\\n\\n- Может быть разобрана обратно на отдельные элементы\\n\\nВажно:\\n\\n- Глубокая вложенность SVG часто «сплющивается»\\n\\n- Не все SVG-атрибуты имеют прямые аналоги\\n\\nСлои в Fabric.js\\nВ Fabric.js нет слоёв как отдельной сущности.\\nИспользуется:\\n\\n- Порядок объектов в `canvas._objects`\\n\\n- Методы `bringToFront`, `sendToBack`\\n\\n- Логическая группировка через `Group`\\n\\nКраткий вывод\\nFabric.js поддерживает группы, но не сохраняет SVG-иерархию полностью. Слои реализуются через порядок объектов, поэтому сложные SVG-структуры требуют дополнительной логики при импорте и управлении сценой.",null],[1310,"Если библиотека «сплющивает» SVG, иерархию можно восстановить на этапе парсинга. Для этого используют исходный SVG DOM или метаданные элементов. Группы собираются вручную на основе `id`, `data-*` атрибутов или вложенности. Далее эта структура маппится на объекты Canvas.","Многие Canvas-библиотеки упрощают SVG-структуру, так как им не нужна полная DOM-иерархия. Однако в сложных редакторах иерархия групп часто критична.\\nОсновная идея восстановления\\nВосстановление строится не на Canvas, а на данных:\\n\\n- SVG содержит полную структуру\\n\\n- Canvas — только результат отрисовки\\n\\nПоэтому сначала нужно сохранить или восстановить структуру, а уже потом работать с Canvas-объектами.\\nПрактические подходы\\n\\n- Парсинг SVG до передачи в библиотеку\\n\\n- Используется `DOMParser`\\n\\n- Проход по `<g>` и дочерним элементам\\n\\n- Формирование собственного дерева\\n\\n- Использование метаданных\\n\\n- `id`\\n\\n- `data-group`\\n\\n- кастомные атрибуты\\n\\n- Маппинг на Canvas-объекты\\n\\n- Каждому Canvas-объекту присваивается ссылка на узел структуры\\n\\n- Группы собираются вручную через `Group`\\n\\nПример логики (упрощённо)\\n\\nОграничения подхода\\n\\n- Требуется дополнительная память\\n\\n- Сложнее синхронизировать изменения\\n\\n- Библиотека может не поддерживать вложенные группы напрямую\\n\\nКраткий вывод\\nИерархия SVG восстанавливается не средствами Canvas, а через предварительный анализ SVG-структуры. Это требует собственной модели данных, но даёт полный контроль над группами и слоями.","// svgNode -> список дочерних элементов\\n// далее создаём fabric.Group на основе этих связей"],[1311,"Canvas не хранит состояние объектов, поэтому его нельзя «откатить» автоматически. Для Undo/Redo нужно самостоятельно сохранять историю изменений. Основные сложности связаны с объёмом данных, производительностью и корректным восстановлением сцены. Часто приходится выбирать между хранением снимков состояния и хранением операций.","Canvas — императивный API, и после отрисовки он не знает, какие объекты и действия к ней привели. Это напрямую влияет на реализацию Undo/Redo.\\nКлючевые сложности\\nПеред реализацией важно понимать основные проблемы:\\n\\n- Отсутствие встроенного состояния\\n\\n- Canvas не знает про фигуры и слои\\n\\n- Всё состояние нужно хранить отдельно\\n\\n- Объём данных\\n\\n- Полные снапшоты сцены могут быть большими\\n\\n- Частые изменения быстро раздувают историю\\n\\n- Производительность\\n\\n- Восстановление состояния может требовать полной перерисовки\\n\\n- Это особенно критично для сложных сцен\\n\\nОсновные подходы\\n\\n- Хранение снимков состояния\\n\\n- сериализация всех объектов\\n\\n- простой откат\\n\\n- большой расход памяти\\n\\n- Хранение команд\\n\\n- сохраняются действия (add, move, resize)\\n\\n- меньше памяти\\n\\n- сложнее реализовать\\n\\nТипичный поток Undo/Redo\\n\\n- действие → запись в историю\\n\\n- Undo → откат состояния\\n\\n- Redo → повтор действия\\n\\nКраткий вывод\\nUndo/Redo для Canvas — это задача управления историей состояния сцены. Выбор между снапшотами и командами зависит от сложности сцены и требований к производительности.",null],[1312,"Графические библиотеки расширяются через их публичные API, плагины или наследование. В крайних случаях используют обёртки или патчи. Важно избегать прямого изменения исходного кода библиотеки. Кастомизация должна быть изолированной и обновляемой.","Сторонние библиотеки редко идеально подходят под конкретный продукт, поэтому их приходится расширять.\\nОсновные способы расширения\\n\\n- Использование публичного API\\n\\n- события\\n\\n- хуки\\n\\n- конфигурационные опции\\n\\n- Наследование и расширение классов\\n\\n- добавление нового поведения\\n\\n- переопределение методов\\n\\n- Обёртки\\n\\n- библиотека используется как «движок»\\n\\n- внешняя логика живёт отдельно\\n\\n- Плагины и middleware\\n\\n- если библиотека поддерживает этот подход\\n\\nЧего стоит избегать\\n\\n- правки кода в `node_modules`\\n\\n- зависимости от приватных методов\\n\\n- логики, жёстко привязанной к версии библиотеки\\n\\nКраткий вывод\\nБезопасная кастомизация строится вокруг публичных API и изоляции изменений. Чем меньше библиотека «ломается» при обновлении, тем лучше архитектурное решение.","class CustomShape extends BaseShape {\\n  // добавляем дополнительную логику\\n}"],[1313,"Canvas 2D — это простой API для отрисовки 2D-графики. WebGL — низкоуровневый интерфейс для работы с GPU и 3D-сценами. Canvas проще в освоении, WebGL — мощнее и производительнее. Выбор зависит от сложности графики и требований к анимации.","Canvas 2D и WebGL решают разные классы задач, несмотря на внешнюю схожесть.\\nCanvas 2D\\nCanvas 2D подходит для:\\n\\n- простых 2D-сцен\\n\\n- UI-графики\\n\\n- диаграмм и редакторов\\n\\nХарактеристики:\\n\\n- императивный API\\n\\n- CPU-рендеринг\\n\\n- простая модель мышления\\n\\nWebGL / 3D\\nWebGL ориентирован на:\\n\\n- сложную анимацию\\n\\n- большие сцены\\n\\n- 3D-графику\\n\\nОсобенности:\\n\\n- работа напрямую с GPU\\n\\n- шейдеры\\n\\n- более высокий порог входа\\n\\nПрактические последствия выбора\\n\\n- Canvas проще поддерживать\\n\\n- WebGL лучше масштабируется по производительности\\n\\n- Для большинства UI-задач WebGL избыточен\\n\\nКраткий вывод\\nCanvas 2D — выбор для простых и средних 2D-задач. WebGL оправдан, когда нужна высокая производительность, сложная анимация или 3D-сцены.",null],[1314,"Three.js может использоваться для добавления 3D-эффектов к 2D-графике. Он позволяет применять аппаратное ускорение, сложные трансформации и анимации. Часто Three.js выступает как рендер-движок, а 2D-графика накладывается поверх или используется как текстуры. Такой подход применяют для визуальных эффектов и интерактивных сцен.","Хотя Three.js ассоциируется с 3D, его часто используют и в гибридных 2D-сценариях.\\nОсновные сценарии использования\\nПеред применением важно понимать, зачем вообще подключать Three.js:\\n\\n- необходимость GPU-ускорения\\n\\n- сложные анимации и эффекты\\n\\n- работа с перспективой и глубиной\\n\\nТипичные варианты интеграции\\n\\n- 2D как текстуры\\n\\n- Canvas или SVG рендерятся в текстуру\\n\\n- текстура применяется к плоскости (`PlaneGeometry`)\\n\\n- Псевдо-3D эффекты\\n\\n- параллакс\\n\\n- наклоны и повороты\\n\\n- depth-based анимации\\n\\n- Сложные визуальные эффекты\\n\\n- blur\\n\\n- glow\\n\\n- постпроцессинг\\n\\nОграничения подхода\\n\\n- выше сложность поддержки\\n\\n- больше кода и абстракций\\n\\n- не всегда оправдано для простых UI-задач\\n\\nКраткий вывод\\nThree.js в связке с 2D-графикой применяют, когда стандартный Canvas не справляется с визуальными требованиями. Это оправдано для эффектов и производительных сцен, но избыточно для обычного UI.","// Canvas используется как texture для Three.js\\nconst texture = new THREE.CanvasTexture(canvas)"],[1315,"Обработчики событий относятся к реактивным и событийно-ориентированным задачам. Они не выполняются постоянно, а срабатывают в ответ на действия пользователя или системы. Такие задачи управляют потоком взаимодействия, а не вычислениями. Это ключевая часть пользовательских интерфейсов.","Обработчики событий — это не бизнес-логика и не вычислительные задачи в чистом виде.\\nХарактер задачи\\nEvent listeners относятся к:\\n\\n- событийно-ориентированному программированию\\n\\n- реактивным системам\\n\\n- управлению пользовательским взаимодействием\\n\\nОни «реагируют», а не инициируют процесс.\\nЧто делают обработчики событий\\n\\n- Получают событие\\n\\n- клик\\n\\n- ввод текста\\n\\n- сетевой ответ\\n\\n- Запускают реакцию\\n\\n- обновление состояния\\n\\n- вызов бизнес-логики\\n\\n- перерисовка UI\\n\\nПочему это важно\\n\\n- события задают жизненный цикл интерфейса\\n\\n- логика становится асинхронной\\n\\n- код должен быть устойчив к частым вызовам\\n\\nКраткий вывод\\nОбработчики событий — это реактивные задачи, управляющие потоком приложения. Они связывают действия пользователя и изменения состояния, но не должны содержать тяжёлую логику.",null],[1316,"`await` внутри условия работает так же, как и в любом другом месте. Выполнение функции приостанавливается до завершения Promise. Условие вычисляется только после получения результата. Это может влиять на производительность и читаемость кода.","`await` не меняет логику условных конструкций, но влияет на порядок выполнения.\\nКак работает `await` в условии\\nКогда `await` используется:\\n\\n- выполнение текущей async-функции приостанавливается\\n\\n- event loop продолжает работу\\n\\n- после завершения Promise код продолжается\\n\\nПрактические последствия\\n\\n- Условие становится асинхронным\\n\\n- результат зависит от Promise\\n\\n- возможна задержка выполнения\\n\\n- Последовательное выполнение\\n\\n- несколько `await` в условиях выполняются по очереди\\n\\n- Потенциальные проблемы\\n\\n- лишние ожидания\\n\\n- сложность чтения логики\\n\\nКогда это оправдано\\n\\n- проверка прав доступа\\n\\n- загрузка конфигурации\\n\\n- валидация перед действием\\n\\nКраткий вывод\\n`await` внутри условий безопасен и предсказуем, но делает поток выполнения асинхронным. Его стоит использовать осознанно, чтобы не усложнять и не замедлять код.","if (await isAllowed()) {\\n  // выполнится только после завершения Promise\\n}"],[1317,"`setTimeout` помещает колбэк в очередь макрозадач. Promise внутри него создаётся и резолвится уже во время выполнения этой макрозадачи. Микрозадачи Promise будут выполнены сразу после завершения текущего колбэка `setTimeout`, но до следующей макрозадачи. Это влияет на порядок выполнения кода.","Асинхронность в JavaScript основана на очередях задач, и `setTimeout` с `Promise` задействуют разные уровни этой системы.\\nОчереди задач в браузере\\nПеред разбором примера важно понимать:\\n\\n- `setTimeout` → макрозадача\\n\\n- `Promise.then` / `await` → микрозадача\\n\\nМикрозадачи всегда выполняются раньше следующей макрозадачи.\\nПорядок выполнения\\n\\nПоследовательность:\\n\\n- Выполняется синхронный код\\n\\n- Колбэк `setTimeout` попадает в очередь макрозадач\\n\\n- После его выполнения добавляется микрозадача Promise\\n\\n- Микрозадача выполняется до следующей макрозадачи\\n\\nПрактические последствия\\n\\n- Promise внутри `setTimeout` не «обгоняет» синхронный код\\n\\n- Но он выполняется раньше других таймеров\\n\\n- Это важно при оптимизации и дебаге асинхронного кода\\n\\nКраткий вывод\\nPromise, созданный внутри `setTimeout`, выполняется в рамках макрозадачи таймера, а его обработчики — как микрозадачи сразу после неё. Понимание этого порядка критично для предсказуемого асинхронного поведения.","setTimeout(() => {\\n  Promise.resolve().then(() => {\\n    console.log(\'promise\')\\n  })\\n}, 0)\\n\\nconsole.log(\'sync\')"],[1318,"Debounce откладывает выполнение функции до тех пор, пока события не прекратятся на заданное время. Это снижает количество обновлений state и ререндеров при вводе текста. Обычно debounce применяют для поиска, фильтрации и запросов к API. В результате интерфейс работает плавнее, а запросов становится меньше.","Ввод в `input` генерирует события очень часто: практически на каждый символ. Если на каждое событие делать тяжёлую работу (рендер, фильтрацию, запрос), приложение начнёт лагать.\\nЧто делает debouncing\\nDebounce — это стратегия “выполнить позже, когда пользователь закончил”.\\n\\n- пользователь печатает → таймер постоянно сбрасывается\\n\\n- пользователь остановился → таймер истёк → функция выполнилась\\n\\nЭто отличается от throttle, где выполнение происходит “не чаще раза в N мс”.\\nТипичные случаи использования\\n\\n- Поиск по мере ввода\\n\\n- не делать запрос на каждый символ\\n\\n- Фильтрация большого списка\\n\\n- не пересчитывать фильтр при каждом вводе\\n\\n- Автосохранение черновика\\n\\n- сохранять после паузы\\n\\nПример debounce без библиотек\\n\\nПрименение в React обычно выглядит как разделение:\\n\\n- `inputValue` обновляется сразу (чтобы UI был отзывчивым)\\n\\n- “debouncedValue” обновляется реже (для тяжёлых действий)\\n\\nВажный момент про состояние и UX\\nЕсли делать debounce прямо на `setState` поля ввода, можно получить плохой UX:\\n\\n- поле “отстаёт” от ввода\\n\\n- курсор ведёт себя странно\\n\\n- кажется, что приложение лагает\\n\\nЧаще правильнее:\\n\\n- ввод отображать мгновенно\\n\\n- дебаунсить эффект (запрос/фильтрацию), а не сам ввод\\n\\nТипичные ошибки\\n\\n- Создание debounce-функции на каждый рендер\\n\\n- тогда таймеры будут сбрасываться непредсказуемо\\n\\n- решение: стабилизировать функцию через `useMemo` / `useCallback`\\n\\n- Забыть очистить таймер при unmount\\n\\n- может привести к обновлению состояния после размонтирования\\n\\n- решение: cleanup в `useEffect`\\n\\nКраткий вывод\\nDebounce нужен, чтобы уменьшить количество тяжёлых операций при частых событиях и сделать UI более плавным. В React обычно обновляют значение input сразу, а debounce применяют к побочным действиям: фильтрации, запросам, автосохранению.","function debounce(fn, delay) {\\n  let t\\n  return (...args) => {\\n    clearTimeout(t)\\n    t = setTimeout(() => fn(...args), delay)\\n  }\\n}\\n\\nconst [value, setValue] = useState(\'\')\\n\\nconst onChange = (e) => setValue(e.target.value)\\n\\n// дальше: debounce либо для запроса, либо для вычислений"],[1319,"Виртуализация без библиотек реализуется через расчёт видимой области и рендер только нужных элементов. Используется контейнер со скроллом, вычисляется диапазон индексов, которые должны быть показаны. Остальное пространство компенсируется отступами. Такой подход требует аккуратных расчётов и оптимизации.","Самописная виртуализация — это управляемый компромисс между сложностью и контролем.\\nБазовая идея\\nНужно ответить на три вопроса:\\n\\n- какая часть списка видна\\n\\n- какие элементы туда попадают\\n\\n- где должен начинаться и заканчиваться контент\\n\\nМинимальный алгоритм\\n\\n- Известны:\\n\\n- высота контейнера\\n\\n- высота одного элемента\\n\\n- По `scrollTop` вычисляется:\\n\\n- `startIndex`\\n\\n- `endIndex`\\n\\n- Рендерятся элементы:\\n\\n- только в диапазоне `[startIndex, endIndex]`\\n\\n- Компенсация прокрутки:\\n\\n- `padding-top` = `startIndex * itemHeight`\\n\\n- `padding-bottom` = `(total - endIndex) * itemHeight`\\n\\nУпрощённый пример логики\\n\\nОсновные сложности\\n\\n- разные высоты элементов\\n\\n- плавность скролла\\n\\n- частые пересчёты при scroll\\n\\n- поддержка resize\\n\\nИз-за этих сложностей библиотеки и остаются популярными.\\nКогда самописная реализация оправдана\\n\\n- очень специфические требования\\n\\n- минимальный бандл\\n\\n- полный контроль над логикой\\n\\nКраткий вывод\\nВиртуализация без библиотек строится на расчёте видимой области и управлении отступами. Это возможно, но требует аккуратной реализации и понимания внутренних механизмов браузера.","const start = Math.floor(scrollTop / itemHeight)\\nconst visibleCount = Math.ceil(containerHeight / itemHeight)\\nconst end = start + visibleCount"],[1320,"Основной API для отслеживания видимости элементов — `IntersectionObserver`. Он позволяет асинхронно узнавать, когда элемент появляется или исчезает из viewport. В более простых случаях используют события скролла и `getBoundingClientRect`, но это менее эффективно. Современные приложения почти всегда выбирают `IntersectionObserver`.","Отслеживание видимости элементов важно для lazy loading, виртуализации и аналитики.\\nОсновной API: IntersectionObserver\\n`IntersectionObserver` сообщает:\\n\\n- когда элемент входит в область видимости\\n\\n- насколько он видим (intersection ratio)\\n\\n- относительно какого контейнера считается видимость\\n\\nКлючевые особенности:\\n\\n- работает асинхронно\\n\\n- не требует ручной обработки scroll-событий\\n\\n- оптимизирован на уровне браузера\\n\\nАльтернативные подходы\\n\\n- Scroll + getBoundingClientRect\\n\\n- ручной расчёт координат\\n\\n- высокая частота вызовов\\n\\n- риск проблем с производительностью\\n\\n- ResizeObserver (косвенно)\\n\\n- отслеживает изменение размеров\\n\\n- используется совместно с IntersectionObserver\\n\\n- Visibility API\\n\\n- определяет, активна ли вкладка\\n\\n- не про элементы, а про страницу целиком\\n\\nКогда что использовать\\n\\n- lazy loading изображений → `IntersectionObserver`\\n\\n- аналитика просмотра блоков → `IntersectionObserver`\\n\\n- простые сценарии → `getBoundingClientRect` (с осторожностью)\\n\\nКраткий вывод\\n`IntersectionObserver` — стандартный и наиболее эффективный способ отслеживать видимость элементов. Ручные решения через scroll подходят только для простых или специфических случаев.","const observer = new IntersectionObserver(entries => {\\n  entries.forEach(entry => {\\n    if (entry.isIntersecting) {\\n      // элемент виден\\n    }\\n  })\\n})\\n\\nobserver.observe(element)"],[1321,"Поиск анаграмм реализуется с помощью скользящего окна и частотных таблиц символов. Сначала считается частота символов искомой подстроки, затем окно той же длины «скользит» по строке. При совпадении частот найдено вхождение. Такой алгоритм работает за линейное время.","Задача поиска анаграмм — классический пример применения техники sliding window.\\nЧто такое анаграмма в этой задаче\\nАнаграмма — это:\\n\\n- те же символы\\n\\n- в любом порядке\\n\\n- с тем же количеством повторений\\n\\nПорядок символов не важен, важна частота.\\nНаивный подход и его проблема\\nНаивное решение:\\n\\n- брать каждую подстроку\\n\\n- сортировать символы\\n\\n- сравнивать с отсортированным образцом\\n\\nМинусы:\\n\\n- сортировка на каждом шаге\\n\\n- сложность выше линейной\\n\\nЭффективный подход: sliding window\\nИдея:\\n\\n- Построить частотную карту подстроки `pattern`\\n\\n- Вести частотную карту текущего окна в строке\\n\\n- Сдвигать окно на один символ\\n\\n- Обновлять частоты, не пересчитывая всё заново\\n\\nПример базовой логики\\n\\nВажно:\\n\\n- длина окна всегда равна длине подстроки\\n\\n- добавляем символ справа\\n\\n- убираем символ слева\\n\\nПочему это эффективно\\n\\n- каждый символ добавляется и удаляется один раз\\n\\n- нет вложенных циклов\\n\\n- сложность O(n)\\n\\nКраткий вывод\\nПоиск анаграмм подстроки в строке эффективно решается через скользящее окно и частотные карты. Это позволяет избежать перебора и сортировки.","// частоты pattern и текущего окна сравниваются\\n// если совпали — найдено вхождение"],[1322,"Для поиска всех индексов используется тот же алгоритм со скользящим окном. При каждом совпадении частот текущего окна с эталоном сохраняется индекс начала окна. В результате возвращается массив всех позиций. Алгоритм остаётся линейным по времени.","Поиск индексов — это логическое расширение задачи поиска самих анаграмм.\\nБазовая идея\\nИспользуется тот же sliding window, но дополнительно:\\n\\n- отслеживается текущая позиция окна\\n\\n- при совпадении частот сохраняется индекс\\n\\nПоследовательность действий\\n\\n- Подготовка\\n\\n- частотная карта подстроки\\n\\n- пустой массив результатов\\n\\n- Инициализация окна\\n\\n- первые `k` символов строки\\n\\n- Сдвиг окна\\n\\n- добавление нового символа\\n\\n- удаление старого\\n\\n- Проверка совпадения\\n\\n- если карты равны → `push(startIndex)`\\n\\nУпрощённый пример структуры\\n\\nНа что важно обратить внимание\\n\\n- корректное обновление частот при сдвиге\\n\\n- одинаковый размер окна\\n\\n- аккуратная работа с символами, частота которых стала нулевой\\n\\nВозможные оптимизации\\n\\n- использование массивов вместо объектов для ограниченного алфавита\\n\\n- счётчик совпавших символов вместо полного сравнения карт\\n\\nКраткий вывод\\nВсе индексы анаграмм находятся тем же алгоритмом скользящего окна, что и одиночные вхождения. Разница лишь в накоплении результатов, а асимптотика остаётся линейной.","const result = []\\n\\n// при совпадении:\\nresult.push(startIndex)"],[1323,"Основной подход для сравнения анаграмм — сравнение частот символов. Если частоты всех символов совпадают, строки являются анаграммами. Сортировка строк возможна, но менее эффективна. Для задач с большими объёмами данных предпочтителен подход с частотными таблицами и линейной сложностью.","Анаграммность определяется не порядком символов, а их количеством. Из этого следует несколько возможных подходов, каждый со своими плюсами и минусами.\\nНаивный подход: сортировка строк\\nИдея проста:\\n\\n- привести обе строки к массиву символов\\n\\n- отсортировать\\n\\n- сравнить результат\\n\\nПроблемы подхода:\\n\\n- сортировка имеет сложность O(n log n)\\n\\n- лишние аллокации памяти\\n\\n- плохо масштабируется для частых проверок\\n\\nИспользуется в основном:\\n\\n- в учебных примерах\\n\\n- при очень коротких строках\\n\\nОсновной подход: частотные таблицы\\nБолее правильная и масштабируемая стратегия — считать частоты символов.\\nОбщая идея:\\n\\n- для первой строки увеличить счётчики символов\\n\\n- для второй строки уменьшить их\\n\\n- в конце все счётчики должны быть равны нулю\\n\\nПреимущества:\\n\\n- линейная сложность O(n)\\n\\n- не зависит от порядка символов\\n\\n- хорошо подходит для sliding window\\n\\nОптимизации для ограниченного алфавита\\nЕсли алфавит известен и ограничен (например, только `a–z`):\\n\\n- можно использовать массив фиксированной длины\\n\\n- это быстрее и экономичнее по памяти\\n\\nПодход со счётчиком совпадений\\nДля задач поиска анаграмм в строке часто используют:\\n\\n- общий счётчик совпавших символов\\n\\n- уменьшение/увеличение его при сдвиге окна\\n\\nЭто позволяет:\\n\\n- не сравнивать таблицы целиком\\n\\n- получить строго линейное время\\n\\nЧто важно учитывать на практике\\n\\n- Длина строк\\n\\n- разная длина → не анаграммы сразу\\n\\n- Набор символов\\n\\n- регистр\\n\\n- пробелы\\n\\n- специальные символы\\n\\n- Частота проверок\\n\\n- единичная проверка\\n\\n- массовый поиск в строке\\n\\nКакой подход выбирать\\n\\n- одиночная проверка, короткие строки → допустима сортировка\\n\\n- частые проверки или поиск в тексте → частотные таблицы\\n\\n- большие объёмы данных → массивы + sliding window\\n\\nКраткий вывод\\nНа практике анаграммы сравнивают через частоты символов, а не сортировку. Это даёт линейную сложность, хорошо масштабируется и легко применяется в задачах поиска и сканирования строк.","const isAnagram = (a, b) =>\\n  a.split(\'\').sort().join(\'\') === b.split(\'\').sort().join(\'\')\\n\\nfunction isAnagram(a, b) {\\n  if (a.length !== b.length) return false\\n\\n  const map = {}\\n\\n  for (const ch of a) map[ch] = (map[ch] || 0) + 1\\n  for (const ch of b) {\\n    if (!map[ch]) return false\\n    map[ch]--\\n  }\\n\\n  return true\\n}\\n\\nconst freq = new Array(26).fill(0)"],[1324,"Плавающие баги нужно сначала стабильно воспроизвести. Важно собрать контекст: окружение, действия пользователя, состояние приложения. Отладка ведётся через логи, изоляцию кода и упрощение сценария. Предположения проверяются по одному. Без воспроизведения баг не считается исправленным.","Нестабильные баги — одни из самых сложных, так как они зависят от времени, состояния или окружения.\\nПервый шаг — воспроизведение\\nБез воспроизведения отладка превращается в угадывание.\\n\\n- фиксация шагов пользователя\\n\\n- проверка разных окружений\\n\\n- анализ частоты появления\\n\\nСбор контекста\\nВажно понять, при каких условиях возникает ошибка:\\n\\n- Состояние приложения\\n\\n- данные\\n\\n- авторизация\\n\\n- флаги\\n\\n- Асинхронность\\n\\n- гонки запросов\\n\\n- несинхронизированные обновления\\n\\n- Окружение\\n\\n- браузер\\n\\n- устройство\\n\\n- сеть\\n\\nПодход к поиску причины\\n\\n- добавление логов в ключевые точки\\n\\n- упрощение сценария до минимума\\n\\n- временное отключение частей логики\\n\\n- проверка предположений по очереди\\n\\nПример:\\n\\nЧастые причины плавающих багов\\n\\n- race condition\\n\\n- stale state\\n\\n- ошибки зависимостей в эффектах\\n\\n- мутация данных\\n\\nВывод\\nПлавающие баги требуют дисциплины и системного подхода. Главная цель — превратить нестабильную ошибку в воспроизводимую, а уже затем устранять её причину.","console.log(\'state before update\', state)"],[1325,"Работу с незнакомым кодом нужно начинать с общего понимания задачи, которую он решает. Далее изучается точка входа и основные зависимости. Важно не вносить изменения сразу, а сначала разобраться в поведении кода. Полезно использовать логи и отладчик. Любые правки должны быть минимальными и проверяемыми.","Работа с незнакомым JavaScript-кодом — регулярная задача в поддержке и развитии существующих проектов.\\nНачальный этап — ориентация в коде\\nПеред анализом деталей важно получить общее представление:\\n\\n- какую бизнес-задачу решает код\\n\\n- где находится точка входа\\n\\n- какие модули и слои задействованы\\n\\nПоследовательность изучения\\n\\n- Чтение «сверху вниз»\\n\\n- входной файл\\n\\n- основные функции или компоненты\\n\\n- Поиск ключевых сущностей\\n\\n- состояние\\n\\n- побочные эффекты\\n\\n- работа с API\\n\\n- Анализ данных\\n\\n- откуда приходят данные\\n\\n- как они трансформируются\\n\\n- куда передаются дальше\\n\\nПрактические инструменты\\n\\n- отладчик браузера\\n\\n- `console.log` в контрольных точках\\n\\n- временное упрощение кода для проверки гипотез\\n\\nПример:\\n\\nПравила безопасных изменений\\n\\n- не переписывать код без понимания\\n\\n- менять одну вещь за раз\\n\\n- сразу проверять поведение\\n\\nВывод\\nРабота с незнакомым кодом — это процесс исследования. Спешка и хаотичные правки почти всегда приводят к новым ошибкам.","console.log(\'current value\', value)"],[1326,"TDD — это подход, при котором тесты пишутся до кода. Сначала описывается ожидаемое поведение, затем реализуется минимальный код. После этого код улучшается без изменения поведения. Такой подход помогает лучше продумывать архитектуру. TDD снижает количество ошибок.","TDD строится вокруг идеи, что поведение системы должно быть описано до её реализации.\\nКлассический цикл TDD\\n\\n- Red\\n\\n- пишется тест\\n\\n- тест падает\\n\\n- Green\\n\\n- пишется минимальный код\\n\\n- тест проходит\\n\\n- Refactor\\n\\n- код упрощается\\n\\n- поведение сохраняется\\n\\nЧто дает TDD на практике\\n\\n- четкое понимание требований\\n\\n- более модульный код\\n\\n- высокая тестируемость\\n\\nКогда TDD особенно полезен\\n\\n- сложная бизнес-логика\\n\\n- библиотеки и утилиты\\n\\n- код с долгим сроком жизни\\n\\nОграничения подхода\\n\\n- требует дисциплины\\n\\n- увеличивает время на старте\\n\\nВывод\\nTDD — это не про тесты, а про способ мышления и проектирования кода через поведение.",null],[1327,"TDD требует высокой дисциплины и опыта. На старте разработка замедляется из-за необходимости писать тесты заранее. Не всегда очевидно, как тестировать UI и асинхронное поведение. При частых изменениях требований тесты приходится постоянно переписывать. Без понимания цели TDD превращается в формальность.","Несмотря на преимущества, TDD не является универсальным решением и имеет ряд практических сложностей.\\nОсновные проблемы TDD\\n\\n- Повышенный порог входа\\n\\n- сложно начать без опыта\\n\\n- трудно писать тесты до кода\\n\\n- Замедление на ранних этапах\\n\\n- больше времени уходит на старт\\n\\n- результат виден не сразу\\n\\n- Неочевидность тестов для UI\\n\\n- сложно заранее описать поведение\\n\\n- много изменений на этапе дизайна\\n\\n- Частые правки тестов\\n\\n- требования меняются\\n\\n- тесты быстро устаревают\\n\\nТипичные ошибки при использовании\\n\\n- написание тестов ради тестов\\n\\n- слишком детальные тесты\\n\\n- тестирование реализации вместо поведения\\n\\nКогда TDD применять не стоит\\n\\n- прототипы и MVP\\n\\n- задачи с высокой неопределенностью\\n\\n- быстро меняющийся UI\\n\\nВывод\\nTDD эффективен при правильном применении и стабильных требованиях. В противном случае он может замедлить разработку и увеличить стоимость изменений.",null],[1328,"jQuery упрощал работу с DOM и кроссбраузерностью в то время, когда нативный API был неудобным и непоследовательным. Он предлагал короткий и единообразный синтаксис для поиска элементов, обработки событий и работы с AJAX. Однако сегодня нативный DOM API стал значительно удобнее и мощнее. jQuery добавляет лишний слой абстракции и вес в бандл. В современных приложениях он используется все реже.","jQuery появился как решение проблем раннего веба, когда браузеры сильно отличались по поведению и возможностям.\\nПреимущества jQuery\\nОсновные сильные стороны jQuery связаны с упрощением разработки:\\n\\n- единый API для разных браузеров\\n\\n- короткий и читаемый синтаксис для работы с DOM\\n\\n- встроенные утилиты для событий, анимаций и AJAX\\n\\n- низкий порог входа для начинающих\\n\\nПример выборки элемента:\\n\\nНедостатки jQuery\\nСо временем его ограничения стали очевидны:\\n\\n- дополнительный вес библиотеки в бандле\\n\\n- избыточность при наличии современного DOM API\\n\\n- сложность интеграции с компонентными фреймворками\\n\\n- устаревшая модель работы с состоянием интерфейса\\n\\nСовременный нативный DOM API\\nСегодня браузеры предоставляют:\\n\\n- `querySelector` и `querySelectorAll`\\n\\n- удобную работу с классами через `classList`\\n\\n- `fetch` вместо jQuery AJAX\\n\\n- единое поведение в большинстве браузеров\\n\\nВывод\\njQuery был полезен в прошлом, но в современных приложениях чаще используют нативный DOM API или фреймворки. Его применение оправдано в легаси-проектах, но не в новых разработках.","// jQuery\\n$(\'#button\')\\n\\n// Нативный API\\ndocument.querySelector(\'#button\')"],[1329,"Событийная модель браузера описывает, как обрабатываются клики, ввод текста и другие действия пользователя. События распространяются по DOM-дереву в определенном порядке. Это позволяет управлять реакцией интерфейса на действия пользователя. Модель нужна для гибкой и предсказуемой обработки событий. Она лежит в основе интерактивности веб-приложений.","Браузер использует событийную модель для того, чтобы элементы страницы могли реагировать на действия пользователя и системные изменения.\\nЧто такое событие\\nСобытие — это сигнал о том, что произошло действие, например:\\n\\n- клик мышью\\n\\n- ввод текста\\n\\n- загрузка страницы\\n\\n- изменение размера окна\\n\\nСобытия привязываются к DOM-элементам с помощью обработчиков.\\nФазы распространения события\\nСобытие проходит несколько фаз:\\n\\n- Фаза погружения — событие идет от `window` к целевому элементу\\n\\n- Целевая фаза — событие достигает элемента\\n\\n- Фаза всплытия — событие поднимается обратно вверх по DOM\\n\\nПо умолчанию обработчики срабатывают на фазе всплытия.\\nЗачем нужна событийная модель\\nОна решает несколько задач:\\n\\n- позволяет обрабатывать действия пользователя\\n\\n- поддерживает делегирование событий\\n\\n- делает поведение интерфейса предсказуемым\\n\\n- упрощает управление сложными иерархиями элементов\\n\\nПример делегирования:\\n\\nВывод\\nСобытийная модель браузера — основа интерактивного веба. Понимание фаз и распространения событий позволяет писать более эффективный и управляемый код.","document.body.addEventListener(\'click\', (event) => {\\n  if (event.target.matches(\'button\')) {\\n    // обработка клика по кнопке\\n  }\\n})"],[1330,"Для получения данных по ID используется `fetch` внутри эффекта, который выполняется при старте приложения. ID может браться из URL или конфигурации. Запрос отправляется после монтирования компонента. Ответ преобразуется в JSON и сохраняется в состоянии. Такой подход позволяет загрузить данные один раз при запуске.","Загрузка данных по ID часто требуется для страниц деталей или стартового состояния приложения.\\nПолучение ID\\nID обычно определяется одним из способов:\\n\\n- из URL\\n\\n- из параметров маршрута\\n\\n- из заранее известной конфигурации\\n\\nПример URL-параметра:\\n\\nВыполнение запроса\\nЗапрос выполняется после монтирования компонента:\\n\\nОбработка состояний\\nПри инициализации важно учитывать:\\n\\n- состояние загрузки\\n\\n- ошибки сети\\n\\n- отсутствие данных\\n\\nЭто делает интерфейс устойчивым к сбоям.\\nВывод\\nПолучение данных по ID при старте приложения реализуется через `fetch` и эффекты. Такой подход прост, нагляден и подходит для большинства сценариев начальной загрузки.","const id = \'42\' // условно получен из URL\\n\\nuseEffect(() => {\\n  fetch(`/api/items/${id}`)\\n    .then(response => response.json())\\n    .then(data => setItem(data))\\n}, [id])"],[1331,"Хороший тест проверяет поведение, а не реализацию. Он должен быть понятным, детерминированным и давать одинаковый результат при каждом запуске. Тест не должен зависеть от внешних факторов и быть хрупким к изменениям кода. Также важно, чтобы тесты быстро выполнялись и легко читались. Плохие тесты усложняют разработку и замедляют команду.","Хорошие тесты помогают уверенно менять код и быстро находить ошибки. Для этого при их написании используют несколько ключевых критериев.\\nОсновные критерии хороших тестов\\n\\n- Проверка поведения, а не реализации\\nТест должен отвечать на вопрос «что делает код», а не «как он это делает».\\n\\n- Детерминированность\\nРезультат теста не должен зависеть от:\\n\\n- времени\\n\\n- случайных значений\\n\\n- состояния окружения\\n\\n- Изолированность\\nКаждый тест должен быть независимым и не влиять на другие тесты.\\n\\n- Понятность и читаемость\\nПо тесту должно быть ясно:\\n\\n- что проверяется\\n\\n- при каких условиях\\n\\n- какой ожидается результат\\n\\n- Минимальная хрупкость\\nНебольшие изменения в коде не должны ломать большое количество тестов.\\n\\nПример хорошего теста\\n\\nВывод\\nХороший тест — это простой, надёжный и читаемый способ зафиксировать поведение системы, а не её внутреннюю реализацию.","expect(calculateTotal(2, 3)).toBe(5)"],[1332,"Автотесты помогают обнаруживать ошибки на раннем этапе и предотвращать регрессии. Они позволяют безопасно вносить изменения в код. Тесты служат дополнительной документацией поведения приложения. Также они повышают уверенность разработчиков при рефакторинге. В долгосрочной перспективе автотесты экономят время команды.","Frontend-приложения быстро растут и часто изменяются, поэтому ручная проверка становится ненадёжной. Автотесты решают эту проблему.\\nОсновные причины использования автотестов\\n\\n- Предотвращение регрессий\\nСтарый функционал продолжает работать после изменений.\\n\\n- Уверенность при рефакторинге\\nМожно менять код, не опасаясь скрытых поломок.\\n\\n- Быстрая обратная связь\\nОшибки обнаруживаются сразу после изменений.\\n\\n- Документирование поведения\\nТесты показывают, как система должна работать.\\n\\n- Повышение качества продукта\\nМеньше багов доходит до пользователя.\\n\\nПример сценария\\n\\nВывод\\nАвтотесты — это инструмент стабильности и скорости разработки, а не просто проверка кода на ошибки.","// тест подтверждает ожидаемое поведение кнопки\\nfireEvent.click(button)\\nexpect(onSubmit).toHaveBeenCalled()"],[1333,"Замыкание формируется в момент создания функции, а не её вызова. Функция запоминает лексическое окружение, в котором была объявлена. Благодаря этому она имеет доступ к внешним переменным даже после завершения их выполнения. Это базовый механизм языка. Он широко используется в практике.","Замыкания — фундаментальный механизм JavaScript, связанный с лексической областью видимости.\\nОпределение\\nЗамыкание — это функция вместе с лексическим окружением, в котором она была создана.\\nКогда формируется замыкание\\n\\n- Во время объявления функции\\nВ этот момент функция «запоминает» внешнюю область видимости.\\n\\n- Независимо от места вызова\\nДаже если функция вызывается в другом месте программы, она продолжает ссылаться на исходное окружение.\\n\\nПример\\n\\nЗдесь внутренняя функция сохраняет доступ к `count`, хотя `createCounter` уже завершила выполнение.\\nПрактическое применение\\n\\n- инкапсуляция состояния\\n\\n- фабрики функций\\n\\n- обработчики событий\\n\\n- мемоизация\\n\\nВывод\\nЗамыкание формируется при создании функции и сохраняет связь с её лексическим окружением. Это позволяет функциям работать с внешними данными даже после завершения внешнего контекста.","function createCounter() {\\n  let count = 0\\n\\n  return function () {\\n    count++\\n    return count\\n  }\\n}\\n\\nconst counter = createCounter()\\ncounter() // 1\\ncounter() // 2"],[1334,"Функция получает доступ к внешней области видимости благодаря лексической области видимости. При создании функции JavaScript запоминает окружение, в котором она была объявлена. При обращении к переменной интерпретатор ищет её сначала внутри функции, затем во внешних областях. Этот поиск идёт по цепочке областей видимости. Такой механизм лежит в основе замыканий.","Доступ функции к внешним переменным — это результат работы лексической модели областей видимости в JavaScript.\\nКак формируется доступ к внешним данным\\nКогда функция создаётся, движок JavaScript:\\n\\n- Фиксирует лексическое окружение\\nФункция «привязывается» к области видимости, в которой она была объявлена, а не вызвана.\\n\\n- Создаёт ссылку на внешнее окружение\\nЭта ссылка используется при поиске переменных.\\n\\n- Использует цепочку областей видимости\\nЕсли переменная не найдена локально, поиск продолжается выше.\\n\\nПорядок поиска переменной\\nПоиск происходит последовательно:\\n\\n- локальные переменные функции\\n\\n- параметры функции\\n\\n- переменные внешней функции или блока\\n\\n- глобальная область видимости\\n\\nПример\\n\\nФункция `inner` получает доступ к `value` из `outer`, потому что именно там она была объявлена.\\nВывод\\nФункция получает доступ к внешней области видимости через лексическое окружение, зафиксированное в момент её создания. Этот механизм делает поведение функций предсказуемым и независимым от места вызова.","const value = 10\\n\\nfunction outer() {\\n  const value = 20\\n\\n  function inner() {\\n    return value\\n  }\\n\\n  return inner\\n}\\n\\nconst fn = outer()\\nfn() // 20"],[1335,"Лексическое окружение — это внутренняя структура, в которой хранятся переменные и ссылки на внешние области видимости. Оно создаётся при входе в блок кода, функцию или модуль. Именно через лексическое окружение JavaScript разрешает имена переменных. Пользователь напрямую с ним не работает, но оно определяет поведение кода. Без него невозможны замыкания.","Лексическое окружение — базовое понятие для понимания работы JavaScript под капотом.\\nОпределение\\nЛексическое окружение — это структура данных, которая содержит:\\n\\n- записи о переменных и функциях\\n\\n- ссылку на внешнее лексическое окружение\\n\\nИз чего состоит лексическое окружение\\n\\n- Environment Record\\nХранит:\\n\\n- переменные\\n\\n- параметры функций\\n\\n- объявления функций\\n\\n- Ссылка на внешнее окружение\\nУказывает, где искать переменные, если они не найдены локально.\\n\\nКогда создаётся лексическое окружение\\n\\n- при выполнении скрипта\\n\\n- при вызове функции\\n\\n- при входе в блок `{}` с `let` и `const`\\n\\nПример\\n\\nДля `inner` создаётся лексическое окружение, содержащее ссылку на окружение `example`.\\nСвязь с замыканиями\\nЗамыкание возникает, когда функция сохраняет доступ к лексическому окружению после выхода из него.\\nВывод\\nЛексическое окружение — это основа механизма областей видимости в JavaScript. Оно определяет, какие переменные доступны в конкретной точке выполнения программы.","function example() {\\n  let x = 5\\n\\n  function inner() {\\n    return x\\n  }\\n\\n  return inner()\\n}"],[1336,"Компилируемый язык преобразуется в машинный код до выполнения программы. Интерпретируемый язык выполняется построчно во время запуска. Это влияет на производительность и способ обнаружения ошибок. На практике граница между этими подходами размыта. JavaScript использует гибридную модель.","Различие между интерпретируемыми и компилируемыми языками связано с тем, когда и как код преобразуется для выполнения.\\nКомпилируемые языки\\nВ таких языках:\\n\\n- исходный код полностью компилируется заранее\\n\\n- создаётся исполняемый файл\\n\\n- ошибки чаще выявляются до запуска\\n\\nПреимущества:\\n\\n- высокая производительность\\n\\n- раннее обнаружение ошибок\\n\\nНедостатки:\\n\\n- отдельный шаг сборки\\n\\n- меньшая гибкость при запуске\\n\\nИнтерпретируемые языки\\nВ таких языках:\\n\\n- код анализируется и выполняется во время запуска\\n\\n- нет отдельного исполняемого файла\\n\\n- ошибки могут возникать во время выполнения\\n\\nПреимущества:\\n\\n- быстрый старт разработки\\n\\n- гибкость и динамичность\\n\\nНедостатки:\\n\\n- потенциально более низкая производительность\\n\\nГде находится JavaScript\\nJavaScript:\\n\\n- не компилируется заранее в классическом смысле\\n\\n- интерпретируется и оптимизируется движком\\n\\n- использует JIT-компиляцию\\n\\nЭто позволяет сочетать гибкость интерпретации и высокую скорость выполнения.\\nВывод\\nИнтерпретируемые и компилируемые языки отличаются моментом преобразования кода. JavaScript использует гибридный подход, что делает его динамичным и достаточно производительным.",null],[1337,"Импорт и экспорт позволяют явно определять, какие части модуля доступны снаружи. Экспортируемые сущности объявляются в одном файле, а импортируются в другом. Связь между модулями создаётся на этапе загрузки, а не во время выполнения функций. Модули выполняются один раз и кэшируются. Это делает код предсказуемым и структурированным.","Модульная система JavaScript основана на явных зависимостях между файлами и строгих правилах их связывания.\\nОсновные принципы работы модулей\\n\\n- Явный экспорт\\nМодуль сам определяет, какие функции или значения доступны извне.\\n\\n- Импорт по ссылке, а не копирование\\nИмпортируемая сущность — это ссылка на экспорт, а не его копия.\\n\\n- Единоразовое выполнение модуля\\nКаждый модуль выполняется только один раз, даже если импортируется в нескольких местах.\\n\\n- Статический анализ\\nИмпорты и экспорты анализируются до выполнения кода, что позволяет:\\n\\n- делать tree shaking\\n\\n- выявлять циклические зависимости\\n\\nПорядок выполнения\\n\\n- сначала загружаются зависимости\\n\\n- затем выполняется код модулей\\n\\n- после этого становятся доступны экспортируемые значения\\n\\nВывод\\nИмпорт и экспорт формируют явные контракты между файлами и позволяют управлять зависимостями на уровне структуры приложения, а не во время выполнения.","export function sum(a: number, b: number) {\\n  return a + b\\n}\\n\\nimport { sum } from \'./math\'"],[1338,"Да, импортированная функция полностью сохраняет доступ к своей лексической области видимости. Импорт не влияет на окружение, в котором функция была объявлена. Функция всегда работает с теми переменными, которые были доступны ей в момент создания. Место вызова не имеет значения. Это следует из лексической модели JavaScript.","Импорт функции из другого файла не меняет её поведение с точки зрения областей видимости.\\nПочему доступ сохраняется\\n\\n- Функция создаётся в своём модуле\\nЛексическое окружение фиксируется в момент объявления функции.\\n\\n- Импорт передаёт ссылку на функцию\\nВместе с функцией сохраняется ссылка на её окружение.\\n\\n- Место вызова не влияет на scope\\nФункция не «перепривязывается» к файлу, где она была импортирована.\\n\\nПример\\n\\nПеременная `count` остаётся частью лексического окружения модуля `counter`.\\nПрактические следствия\\n\\n- модули могут инкапсулировать состояние\\n\\n- возможны скрытые сайд-эффекты\\n\\n- важно аккуратно работать с общим состоянием\\n\\nВывод\\nИмпортированная функция всегда имеет доступ к своей исходной лексической области видимости. Это делает модули предсказуемыми, но требует внимательного отношения к состоянию.","// counter.ts\\nlet count = 0\\n\\nexport function increment() {\\n  count++\\n  return count\\n}\\n\\n// app.ts\\nimport { increment } from \'./counter\'\\n\\nincrement() // 1\\nincrement() // 2"],[1339,"Неправильный кэш может приводить к устаревшим данным и трудноуловимым багам. Часто возникают проблемы с инвалидцией кэша и некорректными ключами. Возможны утечки памяти и несоответствие данных реальному состоянию. Такие ошибки сложно отлаживать. Поэтому кэш требует аккуратной реализации.","Кэширование ускоряет работу приложения, но при ошибках в реализации может создавать больше проблем, чем пользы.\\nТиповые ошибки при реализации кэша\\n\\n- Устаревшие данные\\nКэш не обновляется при изменении исходного источника данных.\\n\\n- Неправильные ключи\\nРазные данные могут сохраняться под одним ключом, что приводит к неверным результатам.\\n\\n- Отсутствие стратегии инвалидции\\nНепонятно:\\n\\n- когда очищать кэш\\n\\n- какие данные считать неактуальными\\n\\n- Утечки памяти\\nКэш растёт без ограничений и никогда не очищается.\\n\\n- Скрытые логические ошибки\\nКод начинает зависеть от наличия кэша, а не от реальных данных.\\n\\nПример проблемы\\n\\nТакой код может ломаться, если закэшированное значение равно `0` или `false`.\\nВывод\\nКэширование требует продуманной стратегии ключей, обновления и очистки. Без этого кэш становится источником нестабильных и трудноотлавливаемых ошибок.","if (cache[key]) {\\n  return cache[key]\\n}"],[1340,"Проверка через falsy ломается, когда закэшированное значение является допустимым, но логически ложным. Значения `0`, `false`, `\'\'` и `null` интерпретируются как отсутствие данных. В результате кэш игнорируется и данные пересчитываются заново. Это приводит к лишним вычислениям и логическим ошибкам. Проблема часто остаётся незаметной.","В JavaScript многие значения приводятся к `false` в логическом контексте, и это создаёт скрытые проблемы при работе с кэшем.\\nЧто считается falsy\\nК falsy-значениям относятся:\\n\\n- `false`\\n\\n- `0`\\n\\n- `\'\'`\\n\\n- `null`\\n\\n- `undefined`\\n\\n- `NaN`\\n\\nВ чём возникает проблема\\nЕсли кэш хранит такие значения, проверка вида:\\n\\nработает некорректно, потому что:\\n\\n- значение в кэше есть\\n\\n- но условие не выполняется\\n\\nТипичные последствия\\n\\n- Повторные вычисления\\nДанные пересчитываются, хотя уже есть в кэше.\\n\\n- Нарушение бизнес-логики\\n`false` или `0` могут быть валидным результатом, но воспринимаются как отсутствие значения.\\n\\n- Трудные для поиска баги\\nОшибка проявляется только при конкретных данных.\\n\\nКорректный подход\\nНужно проверять сам факт наличия ключа:\\n\\nили сравнивать с `undefined`.\\nВывод\\nПроверка через falsy небезопасна для кэша. Корректнее проверять наличие ключа, а не логическое значение данных.","if (cache[key]) {\\n  return cache[key]\\n}\\n\\nif (key in cache) {\\n  return cache[key]\\n}"],[1341,"Конструктор `Promise` выполняется синхронно сразу при создании. Вызовы `then`, `catch` и `finally` регистрируют колбэки синхронно. Но сами колбэки выполняются асинхронно. Они попадают в очередь microtasks. Это гарантирует предсказуемый порядок выполнения.","Promise сочетает в себе синхронное и асинхронное поведение, что часто вызывает путаницу.\\nСинхронные части Promise\\n\\n- Вызов конструктора `Promise`\\nФункция-исполнитель (`executor`) запускается сразу.\\n\\n- Регистрация обработчиков\\nВызовы `then`, `catch`, `finally` выполняются сразу и просто добавляют колбэки.\\n\\nАсинхронные части Promise\\n\\n- Выполнение обработчиков `then` и `catch`\\nДаже если Promise уже resolved, колбэк выполнится асинхронно.\\n\\n- Очередь microtasks\\nКолбэки Promise всегда попадают в microtask queue.\\n\\nПример порядка выполнения\\n\\nРезультат:\\n\\n- `start`\\n\\n- `end`\\n\\n- `then`\\n\\nПочему это важно\\n\\n- влияет на порядок выполнения логики\\n\\n- помогает избегать race condition\\n\\n- важно при отладке асинхронного кода\\n\\nВывод\\nPromise создаётся и настраивается синхронно, но его обработчики всегда выполняются асинхронно через очередь microtasks.","new Promise((resolve) => {\\n  console.log(\'sync\')\\n  resolve(1)\\n})\\n\\nconsole.log(\'start\')\\n\\nPromise.resolve().then(() => {\\n  console.log(\'then\')\\n})\\n\\nconsole.log(\'end\')"],[1342,"`Promise.then` попадает в microtask queue, чтобы выполняться сразу после текущего синхронного кода. Это даёт более высокий приоритет по сравнению с macrotasks. Такой механизм обеспечивает предсказуемость и согласованность асинхронного поведения. Он позволяет Promise работать быстрее, чем таймеры. Это важная часть спецификации JavaScript.","JavaScript использует несколько очередей задач, и Promise имеет особый приоритет.\\nЧто такое microtasks\\nMicrotasks — это очередь задач, которая:\\n\\n- выполняется после завершения текущего стека вызовов\\n\\n- очищается полностью перед переходом к следующей macrotask\\n\\nПочему Promise используют microtasks\\n\\n- Предсказуемый порядок выполнения\\nPromise-колбэки выполняются раньше:\\n\\n- `setTimeout`\\n\\n- `setInterval`\\n\\n- событий DOM\\n\\n- Целостность асинхронных цепочек\\nЦепочки `then` выполняются без вмешательства других задач.\\n\\n- Согласованность со спецификацией\\nТакое поведение гарантировано стандартом и одинаково во всех движках.\\n\\nПример сравнения\\n\\nРезультат:\\n\\n- `promise`\\n\\n- `timeout`\\n\\nПрактическое значение\\n\\n- важно при сложных асинхронных сценариях\\n\\n- помогает избегать неожиданного порядка выполнения\\n\\n- критично для библиотек и фреймворков\\n\\nВывод\\n`Promise.then` выполняется в microtask queue, чтобы гарантировать высокий приоритет и предсказуемый порядок выполнения асинхронного кода.","setTimeout(() => console.log(\'timeout\'), 0)\\n\\nPromise.resolve().then(() => console.log(\'promise\'))"],[1343,"Сначала всегда выполняется весь синхронный код. Затем выполняются microtasks, в том числе обработчики `Promise.then`. Только после этого обрабатываются macrotasks, такие как `setTimeout`. Поэтому вывод в консоль часто отличается от интуитивных ожиданий. Это поведение строго определено спецификацией.","При смешивании синхронного кода и Promise важно понимать приоритеты очередей выполнения.\\nОбщий порядок выполнения\\nJavaScript выполняет код в следующем порядке:\\n\\n- Синхронный код текущего стека\\n\\n- Очередь microtasks\\n\\n- Очередь macrotasks\\n\\nПример\\n\\nПошаговый разбор\\n\\n- Выполняется `console.log(\'A\')`\\n\\n- Регистрируется `then`, но не выполняется\\n\\n- Выполняется `console.log(\'C\')`\\n\\n- Очищается очередь microtasks\\n\\n- Выполняется `console.log(\'B\')`\\n\\nРезультат в консоли:\\n\\n- `A`\\n\\n- `C`\\n\\n- `B`\\n\\nЧастые ошибки\\n\\n- ожидание, что `then` выполнится сразу\\n\\n- путаница между `Promise` и `setTimeout`\\n\\n- неверные предположения о порядке логов\\n\\nВывод\\nПри смешивании Promise и синхронного кода всегда сначала выполняется синхронная часть, затем microtasks. Понимание этого порядка критично для корректной асинхронной логики.","console.log(\'A\')\\n\\nPromise.resolve().then(() => {\\n  console.log(\'B\')\\n})\\n\\nconsole.log(\'C\')"],[1344,"Стрелочные функции не создают собственный `this`, потому что они берут его из внешней лексической области видимости. Такое поведение делает их предсказуемыми и избавляет от необходимости использовать `bind`. Это было сделано специально для упрощения работы с колбэками. Контекст определяется в момент создания функции. Изменить его невозможно.","Стрелочные функции были добавлены в JavaScript для упрощения работы с функциями и контекстом.\\nКак работает this у стрелочных функций\\n\\n- Отсутствие собственного контекста\\nСтрелочная функция не создаёт:\\n\\n- `this`\\n\\n- `arguments`\\n\\n- `super`\\n\\n- Лексическое связывание this\\nЗначение `this` берётся из внешнего лексического окружения.\\n\\n- Фиксация при создании\\nКонтекст определяется в момент объявления функции, а не вызова.\\n\\nПример\\n\\nЗдесь стрелочная функция использует `this` из `Timer`, а не из `setInterval`.\\nПрактические следствия\\n\\n- нельзя использовать `call`, `apply`, `bind`\\n\\n- удобно для обработчиков и колбэков\\n\\n- не подходит для методов объектов\\n\\nВывод\\nСтрелочные функции используют лексический `this`, что делает их поведение стабильным и удобным в асинхронном коде.","function Timer() {\\n  this.seconds = 0\\n\\n  setInterval(() => {\\n    this.seconds++\\n  }, 1000)\\n}"],[1345,"Классы предоставляют более декларативный и читаемый синтаксис для работы с прототипами. Функции-конструкторы требуют ручной работы с `prototype`. Классы вводят ограничения, например запрет вызова без `new`. При этом под капотом используется та же прототипная модель. Различие в основном синтаксическое и поведенческое.","В JavaScript классы и функции-конструкторы решают одну задачу, но делают это разными способами.\\nОсновные отличия\\n\\n- Синтаксис\\nКласс выглядит более структурированным и привычным для разработчиков из других языков.\\n\\n- Ограничения вызова\\nКласс нельзя вызвать без `new`.\\nФункцию-конструктор — можно, что часто приводит к ошибкам.\\n\\n- Работа с методами\\nМетоды класса автоматически добавляются в `prototype`.\\n\\n- Hoisting\\nКлассы не поднимаются так же, как функции.\\n\\nЧто общего\\n\\n- используется прототипное наследование\\n\\n- экземпляры работают одинаково\\n\\n- нет настоящей классической ООП\\n\\nВывод\\nКлассы — это более строгий и удобный синтаксис поверх функций-конструкторов. Они улучшают читаемость кода, но не меняют базовую модель JavaScript.","class User {\\n  constructor(name: string) {\\n    this.name = name\\n  }\\n}"],[1346,"Да, классы в JavaScript являются синтаксическим сахаром над прототипной моделью. Под капотом они используют те же функции-конструкторы и `prototype`. Классы не вводят новую объектную модель, а лишь упрощают синтаксис. Однако они добавляют некоторые ограничения и особенности поведения. Это делает код более безопасным и читаемым.","Классы в JavaScript часто воспринимаются как полноценная реализация классической ООП, но на уровне языка это не так.\\nПочему классы считаются синтаксическим сахаром\\nКлассы:\\n\\n- Используют прототипы\\nВсе методы класса фактически записываются в `ClassName.prototype`.\\n\\n- Основаны на функциях-конструкторах\\nКонструктор класса — это обычная функция, вызываемая через `new`.\\n\\n- Не вводят новую модель наследования\\nНаследование по-прежнему работает через цепочку прототипов.\\n\\nЧто классы всё же добавляют\\n\\n- Более строгие правила\\n\\n- нельзя вызвать класс без `new`\\n\\n- код класса всегда выполняется в строгом режиме\\n\\n- Улучшенную читаемость\\nСтруктура класса явно показывает:\\n\\n- конструктор\\n\\n- методы\\n\\n- наследование\\n\\n- Единый синтаксис для наследования\\n\\nЧто классы не меняют\\n\\n- способ хранения методов\\n\\n- механизм `this`\\n\\n- прототипную природу объектов\\n\\nВывод\\nКлассы в JavaScript — это синтаксический сахар над прототипами с дополнительными ограничениями. Они улучшают читаемость и безопасность кода, но не меняют фундаментальные принципы языка.","class Admin extends User {\\n  getRole() {\\n    return \'admin\'\\n  }\\n}"],[1347,"Контекст `this` определяется в момент вызова функции, а не её объявления. При присваивании метода переменной теряется связь с объектом. В результате функция вызывается как обычная, без контекста. Это приводит к `undefined` или глобальному объекту. Такое поведение — часть спецификации JavaScript.","Потеря `this` — одна из самых частых проблем в JavaScript, особенно при работе с методами объектов.\\nКак определяется this\\nЗначение `this` зависит от формы вызова:\\n\\n- Метод объекта\\n`this` указывает на объект слева от точки.\\n\\n- Обычный вызов функции\\n`this` равен `undefined` в строгом режиме.\\n\\nВ чём возникает проблема\\nКогда метод присваивается переменной:\\n\\nПроисходит следующее:\\n\\n- метод извлекается из объекта\\n\\n- связь с `user` теряется\\n\\n- вызов становится обычным\\n\\nПочему это логично\\nJavaScript не привязывает `this` к функции навсегда.\\nКонтекст определяется исключительно способом вызова.\\nСпособы избежать проблемы\\n\\n- использовать `bind`\\n\\n- вызывать метод через объект\\n\\n- использовать стрелочные функции в качестве колбэков\\n\\nВывод\\nКонтекст `this` теряется при присваивании метода переменной, потому что функция вызывается без объекта-владельца. Это фундаментальное правило языка.","const user = {\\n  name: \'Alex\',\\n  getName() {\\n    return this.name\\n  }\\n}\\n\\nconst fn = user.getName\\nfn()"],[1348,"Метод `bind` создаёт новую функцию с жёстко зафиксированным `this`. Значение контекста больше не зависит от способа вызова. Повторный `bind` не меняет `this`. Это удобно для передачи методов как колбэков. При этом исходная функция не изменяется.","`bind` используется, когда нужно гарантировать конкретный контекст выполнения функции.\\nКак работает bind\\nПри вызове `bind`:\\n\\n- создаётся новая функция\\n\\n- `this` навсегда привязывается к переданному объекту\\n\\n- аргументы могут быть частично зафиксированы\\n\\nОсобенности bind\\n\\n- Невозможность переопределения this\\n`call` и `apply` больше не влияют на контекст.\\n\\n- Возвращается новая функция\\nОригинальная функция остаётся без изменений.\\n\\n- Подходит для колбэков\\nЧасто используется в обработчиках событий и таймерах.\\n\\nОграничения\\n\\n- нельзя использовать для стрелочных функций\\n\\n- усложняет отладку при чрезмерном использовании\\n\\nВывод\\n`bind` фиксирует `this` навсегда для конкретной функции. Это надёжный способ избежать потери контекста при передаче функций.","const user = {\\n  name: \'Alex\'\\n}\\n\\nfunction showName() {\\n  return this.name\\n}\\n\\nconst bound = showName.bind(user)\\nbound() // \'Alex\'"],[1349,"Метод `some` перебирает элементы массива и возвращает `true`, если хотя бы один элемент удовлетворяет условию. Реализация сводится к циклу с ранним выходом. Колбэк вызывается для каждого элемента до первого совпадения. Если условие не выполнено ни разу, возвращается `false`. Поведение строго определено спецификацией.","Реализация `some` помогает понять, как работают встроенные методы массивов и почему они устроены именно так.\\nОбщий принцип работы\\nМетод `some`:\\n\\n- проходит по массиву слева направо\\n\\n- вызывает колбэк для каждого элемента\\n\\n- останавливается при первом `true`\\n\\n- возвращает `true` или `false`\\n\\nПростейшая реализация\\n\\nКлючевые моменты\\n\\n- используется цикл, а не `forEach`\\n\\n- есть досрочный выход\\n\\n- порядок элементов сохраняется\\n\\nВывод\\n`some` — это линейный проход по массиву с возможностью раннего завершения. Его ручная реализация хорошо демонстрирует работу колбэков и условий в JavaScript.","function some<T>(array: T[], callback: (value: T) => boolean): boolean {\\n  for (let i = 0; i < array.length; i++) {\\n    if (callback(array[i])) {\\n      return true\\n    }\\n  }\\n  return false\\n}"],[1350,"Колбэк `some` принимает три аргумента: текущий элемент, его индекс и исходный массив. Использовать можно не все аргументы, а только необходимые. Порядок аргументов фиксирован. Это поведение одинаково для большинства методов массива. Знание сигнатуры упрощает написание кастомных реализаций.","Колбэк функции `some` вызывается с заранее определённым набором аргументов.\\nСигнатура колбэка\\nКолбэк принимает:\\n\\n- Текущий элемент\\nЗначение элемента массива.\\n\\n- Индекс элемента\\nПозиция элемента в массиве.\\n\\n- Исходный массив\\nСсылка на массив, по которому идёт итерация.\\n\\nПример использования\\n\\nПрактические применения аргументов\\n\\n- `value` — основная проверка условия\\n\\n- `index` — логика, зависящая от позиции\\n\\n- `array` — сравнение с другими элементами\\n\\nВывод\\nКолбэк метода `some` всегда получает элемент, индекс и массив. Это делает метод гибким и пригодным для сложных условий.","[1, 2, 3].some((value, index, array) => {\\n  return value > array.length\\n})"],[1351,"Самый надёжный способ — использовать `typeof`. Для функций он возвращает строку `\'function\'`. Это стандартное поведение языка. Проверка проста и быстра. Её достаточно в большинстве случаев.","Проверка аргументов — важная часть защитного программирования, особенно в утилитарных функциях.\\nБазовый способ проверки\\n\\nПочему именно typeof\\n\\n- Стандартное поведение\\n`typeof` корректно определяет функции.\\n\\n- Простота и читаемость\\nПроверка легко понимается при чтении кода.\\n\\n- Предсказуемость\\nРаботает одинаково во всех средах.\\n\\nАльтернативы и ограничения\\n\\n- `instanceof Function` зависит от контекста выполнения\\n\\n- проверка через `Object.prototype.toString` избыточна\\n\\nВывод\\nДля проверки, что аргумент является функцией, достаточно использовать `typeof`. Это самый простой и надёжный способ.","if (typeof callback !== \'function\') {\\n  throw new TypeError(\'Argument must be a function\')\\n}"],[1352,"Ошибку следует выбрасывать сразу при обнаружении некорректного аргумента. Обычно используют `throw` и стандартные классы ошибок, такие как `TypeError` или `Error`. Сообщение ошибки должно быть понятным и описывать проблему. Это упрощает отладку и предотвращает выполнение некорректной логики. Такой подход считается хорошей практикой.","Корректная обработка ошибок начинается с явной проверки входных данных.\\nОбщие принципы выбрасывания ошибок\\n\\n- Ранняя проверка аргументов\\nПроверка должна выполняться в начале функции, до основной логики.\\n\\n- Использование подходящего типа ошибки\\n\\n- `TypeError` — если аргумент неверного типа\\n\\n- `RangeError` — если значение вне допустимого диапазона\\n\\n- `Error` — для общих случаев\\n\\n- Понятное сообщение ошибки\\nСообщение должно объяснять:\\n\\n- какой аргумент некорректен\\n\\n- какое значение ожидалось\\n\\nПример корректной реализации\\n\\nПочему это важно\\n\\n- ошибки обнаруживаются сразу\\n\\n- код становится предсказуемым\\n\\n- упрощается отладка и поддержка\\n\\nВывод\\nПравильное выбрасывание ошибок — это явная проверка аргументов и использование подходящих типов ошибок с понятными сообщениями.","function some<T>(array: T[], callback: (value: T) => boolean): boolean {\\n  if (!Array.isArray(array)) {\\n    throw new TypeError(\'First argument must be an array\')\\n  }\\n\\n  if (typeof callback !== \'function\') {\\n    throw new TypeError(\'Second argument must be a function\')\\n  }\\n\\n  for (let i = 0; i < array.length; i++) {\\n    if (callback(array[i])) {\\n      return true\\n    }\\n  }\\n\\n  return false\\n}"],[1353,"Индекс доступен напрямую из счётчика цикла, используемого при обходе массива. Его нужно передать вторым аргументом в колбэк. Это полностью повторяет поведение стандартного метода `some`. Такой подход прост и нагляден. Он не требует дополнительных структур данных.","При ручной реализации `some` индекс элемента всегда известен, так как перебор массива выполняется через цикл.\\nКак передать индекс в колбэк\\n\\n- Использовать индекс цикла\\nПеременная цикла содержит текущий индекс элемента.\\n\\n- Передать индекс вторым аргументом\\nКолбэк вызывается с тем же набором аргументов, что и в стандартной реализации.\\n\\nПример\\n\\nПрактическая польза индекса\\n\\n- логика, зависящая от позиции элемента\\n\\n- доступ к соседним элементам\\n\\n- отладка и логирование\\n\\nВывод\\nИндекс элемента в кастомной реализации `some` берётся из цикла и передаётся в колбэк вторым аргументом, полностью повторяя стандартное поведение.","function some<T>(\\n  array: T[],\\n  callback: (value: T, index: number) => boolean\\n): boolean {\\n  for (let i = 0; i < array.length; i++) {\\n    if (callback(array[i], i)) {\\n      return true\\n    }\\n  }\\n  return false\\n}"],[1354,"Сам массив передаётся в колбэк третьим аргументом. Это стандартное поведение методов массивов JavaScript. Благодаря этому колбэк имеет доступ ко всему массиву. Такой подход позволяет писать более гибкие условия. Он используется во всех методах итерации.","Встроенные методы массивов передают в колбэк не только элемент, но и контекст итерации.\\nСтандартная сигнатура колбэка\\nКолбэк получает аргументы в следующем порядке:\\n\\n- текущий элемент\\n\\n- индекс элемента\\n\\n- исходный массив\\n\\nРеализация в кастомном some\\n\\nЗачем нужен доступ к массиву\\n\\n- сравнение текущего элемента с другими\\n\\n- проверка длины массива\\n\\n- сложные условия на основе контекста\\n\\nВывод\\nДоступ к массиву внутри колбэка реализуется передачей массива третьим аргументом. Это стандартный и ожидаемый контракт методов массивов.","function some<T>(\\n  array: T[],\\n  callback: (value: T, index: number, array: T[]) => boolean\\n): boolean {\\n  for (let i = 0; i < array.length; i++) {\\n    if (callback(array[i], i, array)) {\\n      return true\\n    }\\n  }\\n  return false\\n}"],[1355,"`some` проверяет, существует ли хотя бы один элемент, удовлетворяющий условию. `every` проверяет, что условие выполняется для всех элементов. `filter` возвращает новый массив с элементами, прошедшими проверку. Эти методы решают разные задачи, хотя используют похожий колбэк. Неправильный выбор метода приводит к лишним вычислениям и менее читаемому коду.","Методы `some`, `every` и `filter` выглядят похожими, но предназначены для разных сценариев.\\nНазначение каждого метода\\n\\n- some\\nВозвращает `true`, если хотя бы один элемент удовлетворяет условию.\\nИспользуется для проверки факта существования подходящего элемента.\\n\\n- every\\nВозвращает `true`, только если все элементы массива проходят проверку.\\nПодходит для валидации данных или проверки инвариантов.\\n\\n- filter\\nВозвращает новый массив элементов, удовлетворяющих условию.\\nИспользуется, когда нужен результат, а не просто булево значение.\\n\\nКлючевые различия в поведении\\n\\n- Возвращаемое значение\\n\\n- `some` → `boolean`\\n\\n- `every` → `boolean`\\n\\n- `filter` → `array`\\n\\n- Досрочное завершение\\n\\n- `some` останавливается при первом `true`\\n\\n- `every` останавливается при первом `false`\\n\\n- `filter` всегда проходит весь массив\\n\\n- Производительность\\nДля простых проверок `some` и `every` предпочтительнее, так как могут завершиться раньше.\\n\\nПример\\n\\nВывод\\n`some` и `every` используются для логических проверок, а `filter` — для получения данных. Выбор метода должен соответствовать цели, иначе код становится менее эффективным и читаемым.","const numbers = [1, 2, 3, 4]\\n\\nnumbers.some(n => n > 3)   // true\\nnumbers.every(n => n > 0)  // true\\nnumbers.filter(n => n > 2) // [3, 4]"],[1356,"Метод `some` завершается досрочно, когда колбэк возвращает `true`. После этого дальнейшая итерация массива прекращается. Это позволяет избежать лишних вычислений. Такое поведение заложено в спецификации. Оно делает метод эффективным для проверок.","Одной из ключевых особенностей `some` является возможность раннего завершения перебора массива.\\nУсловие досрочного завершения\\n`some` прекращает выполнение, если:\\n\\n- колбэк вернул `true` хотя бы для одного элемента\\n\\n- дальнейшая проверка становится бессмысленной\\n\\nКак это выглядит на практике\\n\\nПорядок выполнения:\\n\\n- проверяется `1` → `false`\\n\\n- проверяется `2` → `false`\\n\\n- проверяется `3` → `true`\\n\\n- перебор останавливается\\n\\n`4` уже не будет обработан.\\nПочему это важно\\n\\n- повышает производительность\\n\\n- уменьшает количество вызовов колбэка\\n\\n- позволяет использовать `some` как логическую проверку\\n\\nВывод\\nМетод `some` всегда завершается досрочно при первом `true` из колбэка. Это делает его эффективным инструментом для поиска и проверок условий в массиве.","[1, 2, 3, 4].some(value => {\\n  console.log(value)\\n  return value > 2\\n})"],[1357,"`cookie` и `sessionStorage` используются для хранения данных в браузере.\\nCookie автоматически отправляются на сервер с каждым HTTP-запросом.\\n`sessionStorage` доступен только на клиенте и живет в рамках одной вкладки.\\nОни отличаются по объему, времени жизни и области применения.","В браузере существует несколько механизмов хранения данных, каждый из которых решает свои задачи.\\nОпределение\\nCookie — это небольшие данные, которые браузер хранит и отправляет серверу при каждом запросе.\\nsessionStorage — это клиентское хранилище данных, существующее в рамках одной вкладки браузера.\\nОсновные отличия\\nCookie и sessionStorage различаются по ключевым параметрам:\\n\\n- Область видимости\\n\\n- Cookie доступны серверу и клиенту\\n\\n- sessionStorage доступен только в браузере\\n\\n- Время жизни\\n\\n- Cookie могут иметь заданный срок жизни\\n\\n- sessionStorage очищается при закрытии вкладки\\n\\n- Отправка на сервер\\n\\n- Cookie отправляются автоматически\\n\\n- sessionStorage не участвует в HTTP-запросах\\n\\n- Объем данных\\n\\n- Cookie ограничены по размеру\\n\\n- sessionStorage хранит больше данных\\n\\nПример использования\\n\\nВывод\\nCookie используются для серверных сценариев, например авторизации. sessionStorage подходит для временного клиентского состояния внутри вкладки.","sessionStorage.setItem(\'theme\', \'dark\');"],[1358,"`sessionStorage` используется для хранения данных в рамках одной вкладки браузера.\\nДанные сохраняются при обновлении страницы, но удаляются при закрытии вкладки.\\nОн подходит для временного UI-состояния.\\nЧасто применяется там, где данные не должны сохраняться надолго.","sessionStorage решает задачу краткоживущего хранения данных на клиенте без участия сервера.\\nНазначение sessionStorage\\nЭтот механизм подходит для данных, которые:\\n\\n- Нужны только в рамках одной вкладки\\n\\n- Не должны передаваться на сервер\\n\\n- Не должны сохраняться после закрытия вкладки\\n\\nТипичные сценарии использования\\nНа практике sessionStorage применяют для:\\n\\n- Временных фильтров и настроек интерфейса\\n\\n- Данных многошаговых форм\\n\\n- UI-флагов (открыт модал, выбран таб)\\n\\n- Кеша промежуточных вычислений\\n\\nПример\\n\\nОграничения\\n\\n- Данные не шарятся между вкладками\\n\\n- Полностью очищается при закрытии вкладки\\n\\n- Не подходит для долгосрочного хранения\\n\\nВывод\\nsessionStorage используется для кратковременного клиентского состояния. Это простой и безопасный способ хранить данные в рамках одной сессии вкладки.","sessionStorage.setItem(\'step\', \'2\');\\nconst step = sessionStorage.getItem(\'step\');"],[1359,"`==` сравнивает значения с приведением типов.\\n`===` сравнивает и значение, и тип без приведения.\\n`===` предсказуемее и безопаснее.\\nВ современном коде рекомендуется использовать `===`.","В JavaScript существуют два оператора сравнения на равенство, которые ведут себя по-разному.\\nОпределение\\n`==` (loose equality) — сравнивает значения с автоматическим приведением типов.\\n`===` (strict equality) — сравнивает значение и тип без приведения.\\nКак работает `==`\\nПри сравнении `==` JavaScript может преобразовывать типы:\\n\\n- строку в число\\n\\n- `null` и `undefined`\\n\\n- логические значения\\n\\nПример:\\n\\nКак работает `===`\\n`===` не выполняет преобразований:\\n\\nПочему предпочтительнее `===`\\n\\n- Предсказуемое поведение\\n\\n- Меньше скрытых ошибок\\n\\n- Проще читать и поддерживать код\\n\\nВывод\\n`===` следует использовать по умолчанию. `==` допустим только при полном понимании правил приведения типов.","0 == false      // true\\n\'\' == 0         // true\\nnull == undefined // true\\n\\n0 === false     // false\\n\'\' === 0        // false"],[1360,"В JavaScript у каждого объекта есть ссылка на прототип, доступная через `Object.getPrototypeOf`. Рекурсивный обход прототипной цепочки заключается в последовательном получении прототипа, затем прототипа прототипа и так далее, пока не будет достигнут `null`. Это используется для поиска свойств, методов или анализа структуры наследования. Такой подход помогает понять, откуда объект получает то или иное поведение. Также он полезен при отладке и написании утилит.","Прототипная цепочка определяет механизм наследования в JavaScript. Когда свойство не найдено в самом объекте, поиск продолжается в его прототипе и далее вверх по цепочке.\\nЧто такое прототипная цепочка\\nПрототипная цепочка — это последовательность объектов, связанных через внутреннюю ссылку `[[Prototype]]`.\\n\\n- Каждый объект имеет прототип (кроме `Object.prototype`)\\n\\n- Верхней точкой цепочки является `null`\\n\\n- Поиск свойств происходит снизу вверх\\n\\nРекурсивный обход прототипов\\nДля обхода используется стандартный API.\\n\\nВ этом примере:\\n\\n- Сначала обрабатывается сам объект\\n\\n- Затем его прототип\\n\\n- Обход завершается при достижении `null`\\n\\nЗачем это может понадобиться\\nРекурсивный обход прототипов применяется в нескольких случаях.\\n\\n- Отладка\\n\\n- Понимание, откуда пришёл метод\\n\\n- Анализ неожиданных переопределений\\n\\n- Метапрограммирование\\n\\n- Написание полифиллов\\n\\n- Создание инструментов инспекции объектов\\n\\n- Проверка наличия свойства\\n\\n- Поиск свойства без использования `in`\\n\\n- Контроль только собственных или унаследованных свойств\\n\\nВывод\\nРекурсивный обход прототипной цепочки полезен для глубокого понимания работы объектов и наследования в JavaScript, особенно при отладке и создании вспомогательных инструментов.","function walkPrototypeChain(obj) {\\n  if (obj === null) return;\\n  console.log(obj);\\n  walkPrototypeChain(Object.getPrototypeOf(obj));\\n}"],[1361,"Замыкание возникает, когда внутренняя функция запоминает переменные из внешней функции, даже после её завершения. JavaScript сохраняет ссылку на лексическое окружение, в котором функция была создана. Благодаря этому внутренняя функция может читать и изменять эти переменные. Замыкания часто используются для инкапсуляции данных. Это один из базовых механизмов языка.","Замыкания являются следствием лексической области видимости в JavaScript. Функции запоминают контекст, в котором они были объявлены.\\nОпределение\\nЗамыкание — это комбинация функции и лексического окружения, в котором она была создана.\\nКак это работает\\nКогда функция создаётся:\\n\\n- Она получает ссылку на внешние переменные\\n\\n- Эти переменные сохраняются в памяти\\n\\n- Они не удаляются после завершения внешней функции\\n\\nПример простого замыкания:\\n\\nЗдесь:\\n\\n- `count` принадлежит внешней функции\\n\\n- Внутренняя функция сохраняет к нему доступ\\n\\n- Значение не сбрасывается между вызовами\\n\\nГде используются замыкания\\n\\n- Инкапсуляция состояния\\n\\n- Скрытие внутренних переменных\\n\\n- Контроль доступа к данным\\n\\n- Функции-фабрики\\n\\n- Создание конфигурируемых функций\\n\\n- Переиспользование логики\\n\\n- Обработчики событий и колбэки\\n\\n- Сохранение контекста\\n\\n- Работа с асинхронным кодом\\n\\nВозможные проблемы\\n\\n- Утечки памяти при неправильном использовании\\n\\n- Сложность отладки при вложенных замыканиях\\n\\nВывод\\nЗамыкания позволяют функциям сохранять состояние и доступ к переменным внешнего контекста, что делает их мощным инструментом для управления данными и логикой.","function createCounter() {\\n  let count = 0;\\n\\n  return function () {\\n    count++;\\n    return count;\\n  };\\n}\\n\\nconst counter = createCounter();\\ncounter(); // 1\\ncounter(); // 2"],[1362,"`v-if` лучше использовать, когда условие меняется редко или компонент тяжёлый для отрисовки. `v-show` предпочтительнее, если элемент нужно часто показывать и скрывать. `v-if` полностью добавляет и удаляет элемент из DOM, а `v-show` лишь меняет его видимость через CSS. Это влияет на скорость переключений и начальную загрузку. Выбор зависит от сценария использования.","Хотя `v-if` и `v-show` решают одну задачу, их применение оптимально в разных ситуациях.\\nКогда использовать v-if\\n`v-if` управляет созданием и уничтожением DOM-элементов.\\nИспользование оправдано, если:\\n\\n- Условие меняется редко\\n\\n- Компонент сложный или тяжёлый\\n\\n- Необходимо полностью освобождать ресурсы\\n\\nПример:\\n\\nВ этом случае:\\n\\n- Компонент не создаётся без необходимости\\n\\n- Не выполняются лишние вычисления\\n\\n- Не тратится память на неиспользуемый DOM\\n\\nКогда использовать v-show\\n`v-show` управляет только видимостью элемента.\\nИспользование оправдано, если:\\n\\n- Видимость часто переключается\\n\\n- Важно быстрое отображение\\n\\n- Компонент должен сохранять своё состояние\\n\\nПример:\\n\\nЗдесь:\\n\\n- Элемент создаётся один раз\\n\\n- Переключение происходит быстро\\n\\n- Состояние компонента сохраняется\\n\\nПрактическое правило\\nПеред выбором директивы стоит задать вопрос:\\n\\n- Что дороже — частое переключение или начальная отрисовка?\\n\\nВывод\\n`v-if` подходит для редких условий и тяжёлых компонентов, `v-show` — для частого скрытия и показа элементов без пересоздания DOM.","<HeavyComponent v-if=\\"isAuthorized\\" />\\n\\n<div v-show=\\"isOpen\\">\\n  Меню\\n</div>"],[1363,"При использовании `keep-alive` компоненты не уничтожаются при скрытии. Вместо стандартных хуков уничтожения используются специальные хуки активации и деактивации. Это `activated` и `deactivated`. Они позволяют реагировать на повторное отображение компонента. Такой механизм используется для кэширования состояния.","`keep-alive` — это встроенный компонент Vue, который кэширует динамические компоненты и сохраняет их состояние.\\nКак работает keep-alive\\nПри оборачивании компонента в `keep-alive`:\\n\\n- Компонент не уничтожается при смене маршрута\\n\\n- DOM может быть временно удалён\\n\\n- Состояние компонента сохраняется в памяти\\n\\nСпециальные хуки keep-alive\\nДля работы с кэшируемыми компонентами Vue предоставляет дополнительные хуки.\\n\\n- `activated`\\n\\n- Вызывается при активации компонента\\n\\n- Аналог повторного отображения\\n\\n- Подходит для обновления данных\\n\\n- `deactivated`\\n\\n- Вызывается при деактивации компонента\\n\\n- Компонент скрывается, но не уничтожается\\n\\n- Используется для приостановки логики\\n\\nПример:\\n\\nОтличие от обычного жизненного цикла\\n\\n- `beforeUnmount` и `unmounted` не вызываются\\n\\n- Компонент остаётся в памяти\\n\\n- Состояние не сбрасывается\\n\\nВывод\\nПри использовании `keep-alive` жизненный цикл дополняется хуками `activated` и `deactivated`, которые позволяют управлять логикой кэшируемых компонентов без их уничтожения.","export default {\\n  activated() {\\n    // обновление данных при возврате\\n  },\\n  deactivated() {\\n    // пауза таймеров или подписок\\n  }\\n};"],[1364,"До создания DOM-дерева во Vue доступны хуки `beforeCreate` и `created`. В `beforeCreate` ещё нельзя работать с данными и методами. В `created` уже доступны данные, вычисляемые свойства и методы. Однако DOM на этом этапе ещё не существует. Эти хуки используются для инициализации логики, не связанной с DOM.","Перед монтированием компонента Vue проходит начальный этап инициализации, на котором DOM ещё не создан.\\nХук beforeCreate\\nЭтот хук вызывается самым первым.\\nОсобенности:\\n\\n- Реактивные данные недоступны\\n\\n- Методы и computed ещё не инициализированы\\n\\n- Используется крайне редко\\n\\nПример использования ограничен логикой, не зависящей от состояния компонента.\\nХук created\\nНа этом этапе инициализация данных завершена.\\nВозможности:\\n\\n- Доступны `data`, `methods`, `computed`\\n\\n- Можно подписываться на события\\n\\n- Можно инициировать загрузку данных\\n\\nПример:\\n\\nЧто недоступно на этом этапе\\n\\n- DOM-элементы\\n\\n- refs\\n\\n- Работа с размерами и позициями элементов\\n\\nВывод\\nХуки `beforeCreate` и `created` используются для ранней инициализации логики компонента, когда DOM ещё не существует и работать с ним нельзя.","export default {\\n  created() {\\n    this.fetchData(); // DOM ещё недоступен\\n  }\\n};"],[1365,"Если добавить новое свойство в объект после его инициализации, Vue не сделает его реактивным автоматически. Такое свойство не будет отслеживаться системой реактивности. В результате изменения этого свойства не вызовут обновление шаблона. Это связано с тем, как Vue перехватывает доступ к свойствам. Для корректной работы нужно использовать специальные методы.","Реактивность во Vue основана на отслеживании свойств, которые существуют в момент инициализации компонента.\\nПочему возникает проблема\\nВо время создания компонента Vue:\\n\\n- Проходит по всем свойствам объекта\\n\\n- Делает их реактивными\\n\\n- Запоминает зависимости\\n\\nЕсли свойство добавляется позже:\\n\\n- Vue не знает о его существовании\\n\\n- Геттеры и сеттеры для него не создаются\\n\\n- Изменения не отслеживаются\\n\\nПример проблемы:\\n\\nПоследствия\\n\\n- Шаблон не обновляется\\n\\n- computed и watch не реагируют\\n\\n- Поведение может выглядеть как баг\\n\\nКогда это особенно критично\\n\\n- Работа с формами\\n\\n- Динамическое расширение объектов\\n\\n- Обновление данных из API\\n\\nВывод\\nДобавление новых свойств в объект после инициализации не делает их реактивными, поэтому такие изменения не приводят к обновлению интерфейса без специальных приёмов.","data() {\\n  return {\\n    user: {\\n      name: \'Alex\'\\n    }\\n  };\\n}\\n\\n// позже\\nthis.user.age = 30; // не реактивно"],[1366,"`computed` следует использовать для значений, которые зависят от реактивных данных и используются в шаблоне. Методы лучше подходят для действий или вычислений, которые выполняются по событию. Если нужен кэшируемый результат — выбирают `computed`. Если логика должна выполняться каждый раз — метод. Это помогает избежать лишних перерисовок.","Выбор между `computed` и методами напрямую влияет на читаемость кода и производительность приложения.\\nКогда использовать computed\\n`computed` подходит для производных данных.\\nИспользуется, если:\\n\\n- Значение зависит от реактивного состояния\\n\\n- Результат используется в шаблоне\\n\\n- Важно кэширование\\n\\nПример:\\n\\nКогда использовать методы\\nМетоды подходят для выполнения логики.\\nИспользуются, если:\\n\\n- Вычисление вызывается по событию\\n\\n- Нужны параметры\\n\\n- Кэширование не требуется\\n\\nПример:\\n\\nЧастая ошибка\\nИспользовать методы вместо `computed` в шаблоне, что приводит к лишним вычислениям при каждом рендере.\\nВывод\\n`computed` используется для кэшируемых производных данных, а методы — для действий и вычислений, запускаемых по необходимости.","<p>{{ filteredItems }}</p>\\n\\ncomputed: {\\n  filteredItems() {\\n    return this.items.filter(item => item.active);\\n  }\\n}\\n\\nmethods: {\\n  handleClick() {\\n    this.logAction();\\n  }\\n}"],[1367,"Если не очищать подписки и события, компонент может продолжать работать после своего уничтожения. Это приводит к утечкам памяти и неожиданному поведению приложения. Обработчики событий могут вызываться для уже несуществующего компонента. Со временем такие ошибки накапливаются. Поэтому очистка ресурсов — обязательная часть жизненного цикла.","Компоненты во Vue часто подписываются на внешние источники событий, которые живут дольше самого компонента.\\nЧто считается подписками и событиями\\nПодписками могут быть:\\n\\n- обработчики событий браузера\\n\\n- таймеры и интервалы\\n\\n- подписки на store или event bus\\n\\n- WebSocket и SSE соединения\\n\\nЧто происходит без очистки\\nЕсли компонент уничтожается, но подписка остаётся:\\n\\n- Утечки памяти\\n\\n- ссылки на компонент сохраняются\\n\\n- сборщик мусора не может освободить память\\n\\n- Ошибки выполнения\\n\\n- код пытается обновить уничтоженный компонент\\n\\n- возможны ошибки доступа к состоянию\\n\\n- Неожиданное поведение\\n\\n- события обрабатываются несколько раз\\n\\n- данные обновляются в «невидимых» компонентах\\n\\nПример проблемы\\n\\nБез очистки обработчик останется активным даже после удаления компонента.\\nВывод\\nОчистка подписок и событий предотвращает утечки памяти и гарантирует корректное поведение приложения при смене компонентов.","mounted() {\\n  window.addEventListener(\'resize\', this.onResize);\\n}"],[1368,"Отписываться от событий следует перед уничтожением компонента. В Vue для этого используются хуки `beforeUnmount` и `unmounted`. В Vue 2 аналогами являются `beforeDestroy` и `destroyed`. Это гарантирует, что компонент больше не будет реагировать на внешние события. Такой подход предотвращает ошибки и утечки памяти.","Правильный момент для очистки ресурсов — этап уничтожения компонента.\\nОсновные хуки для отписки\\n\\n- `beforeUnmount`\\n\\n- Компонент ещё существует\\n\\n- Есть доступ к состоянию и методам\\n\\n- Рекомендуемый хук для очистки\\n\\n- `unmounted`\\n\\n- Компонент уже удалён из DOM\\n\\n- Используется реже\\n\\nДля Vue 2:\\n\\n- `beforeDestroy`\\n\\n- `destroyed`\\n\\nПример корректной отписки\\n\\nОсобые случаи\\nПри использовании `keep-alive`:\\n\\n- `beforeUnmount` не вызывается\\n\\n- очистку логики переносят в `deactivated`\\n\\nВывод\\nПодписки и события следует очищать в хуках уничтожения компонента, чтобы избежать утечек памяти и некорректного поведения.","mounted() {\\n  window.addEventListener(\'resize\', this.onResize);\\n},\\nbeforeUnmount() {\\n  window.removeEventListener(\'resize\', this.onResize);\\n}"],[1369,"`package.json` описывает проект и его зависимости. В нём хранятся имена библиотек, версии, скрипты и метаданные проекта. Этот файл используется менеджерами пакетов для установки зависимостей. Он определяет, как проект собирается и запускается. Без него невозможна стандартная работа с npm или yarn.","`package.json` — центральный конфигурационный файл JavaScript-проекта.\\nОсновные задачи package.json\\nФайл выполняет сразу несколько ролей.\\n\\n- Описание проекта\\n\\n- имя и версия проекта\\n\\n- описание и лицензия\\n\\n- Управление зависимостями\\n\\n- `dependencies`\\n\\n- `devDependencies`\\n\\n- версии используемых библиотек\\n\\n- Скрипты проекта\\n\\n- команды сборки\\n\\n- запуск приложения\\n\\n- тестирование\\n\\nПример:\\n\\nВзаимодействие с инструментами\\n`package.json` используется:\\n\\n- npm, yarn, pnpm\\n\\n- сборщиками и тестовыми фреймворками\\n\\n- CI/CD системами\\n\\nВывод\\n`package.json` задаёт структуру проекта, управляет зависимостями и описывает способы его запуска и сборки.","{\\n  \\name\\": \\"my-app\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"scripts\\": {\\n    \\"dev\\": \\"vite\\",\\n    \\"build\\": \\"vite build\\"\\n  }\\n}"],[1370,"`package.json` описывает зависимости и допустимые диапазоны их версий. `package-lock.json` фиксирует конкретные версии установленных пакетов и их дерево зависимостей. `package.json` нужен для описания проекта, а `package-lock.json` — для воспроизводимых установок. Они дополняют друг друга. Вместе они обеспечивают стабильность окружения.","В JavaScript-проектах используется два файла для работы с зависимостями, каждый из которых решает свою задачу.\\nНазначение package.json\\n`package.json` описывает требования проекта.\\nОн содержит:\\n\\n- список зависимостей\\n\\n- версии или диапазоны версий\\n\\n- скрипты и метаданные проекта\\n\\nПример версии зависимости:\\n\\nЭто означает, что допустимы обновления в рамках мажорной версии.\\nНазначение package-lock.json\\n`package-lock.json` фиксирует результат установки зависимостей.\\nОсобенности:\\n\\n- содержит точные версии пакетов\\n\\n- описывает полное дерево зависимостей\\n\\n- автоматически генерируется npm\\n\\nЭтот файл гарантирует, что:\\n\\n- все разработчики получают одинаковые версии пакетов\\n\\n- сборка в CI совпадает с локальной средой\\n\\nКлючевое различие\\n`package.json` отвечает на вопрос:\\n\\n- какие зависимости нужны проекту\\n\\n`package-lock.json` отвечает на вопрос:\\n\\n- какие версии реально установлены\\n\\nВывод\\n`package.json` задаёт правила, а `package-lock.json` фиксирует конкретное состояние зависимостей, обеспечивая воспроизводимость сборки.","eact\\": \\"^18.2.0\\""],[1371,"Версии зависимостей фиксируются с помощью диапазонов версий в `package.json` и lock-файла. Диапазоны задают допустимые обновления, а lock-файл фиксирует точные версии. Это позволяет контролировать обновления и сохранять стабильность. Такой подход используется во всех современных проектах. Он снижает риск поломок.","Фиксация версий зависимостей — важная часть стабильной разработки.\\nДиапазоны версий в package.json\\nВ `package.json` версии указываются с помощью специальных символов.\\nОсновные варианты:\\n\\n- `1.2.3` — строго фиксированная версия\\n\\n- `^1.2.3` — разрешены минорные и патч-обновления\\n\\n- `~1.2.3` — разрешены только патч-обновления\\n\\n- `*` — разрешена любая версия\\n\\nПример:\\n\\nРоль lock-файла\\nLock-файл:\\n\\n- сохраняет точные версии\\n\\n- фиксирует вложенные зависимости\\n\\n- используется при каждой установке\\n\\nДаже если диапазон допускает обновление, lock-файл не изменится без явного обновления зависимостей.\\nПрактические рекомендации\\n\\n- Использовать lock-файл и коммитить его в репозиторий\\n\\n- Обновлять зависимости осознанно\\n\\n- Избегать слишком широких диапазонов\\n\\nВывод\\nВерсии зависимостей фиксируются комбинацией диапазонов в `package.json` и точных значений в lock-файле, что обеспечивает баланс гибкости и стабильности.","\\"axios\\": \\"~1.6.0\\""],[1372,"Lock-файл гарантирует, что у всех разработчиков будут одинаковые версии зависимостей. Это предотвращает ошибки, которые возникают только у части команды. Он делает сборки воспроизводимыми. Особенно важен lock-файл в CI и production. Без него сложно обеспечить стабильность.","В командной разработке важно, чтобы проект одинаково работал у всех участников.\\nПроблемы без lock-файла\\nБез lock-файла:\\n\\n- у разных разработчиков могут быть разные версии пакетов\\n\\n- ошибки сложно воспроизвести\\n\\n- сборка может отличаться в CI и локально\\n\\nЧто даёт lock-файл\\nLock-файл обеспечивает:\\n\\n- одинаковое дерево зависимостей\\n\\n- предсказуемые сборки\\n\\n- стабильное поведение приложения\\n\\nВлияние на CI/CD\\nВ CI:\\n\\n- используются те же версии, что и у разработчиков\\n\\n- сборка становится детерминированной\\n\\n- снижается риск «работает у меня»\\n\\nПрактика в командах\\n\\n- lock-файл всегда хранится в репозитории\\n\\n- изменения в нём проходят код-ревью\\n\\n- обновления зависимостей выполняются отдельно\\n\\nВывод\\nИспользование lock-файла — обязательное условие стабильной командной разработки и надёжных сборок.",null],[1373,"Современные IDE имеют встроенные инструменты для работы с зависимостями. Они позволяют устанавливать, обновлять и удалять пакеты без ручного редактирования файлов. IDE также подсвечивают устаревшие версии и конфликты. Это упрощает поддержку проекта. Работа с зависимостями становится безопаснее и нагляднее.","Современные IDE значительно упрощают управление зависимостями за счёт интеграции с менеджерами пакетов.\\nИнтеграция с менеджерами пакетов\\nIDE напрямую работают с:\\n\\n- npm\\n\\n- yarn\\n\\n- pnpm\\n\\nЧерез интерфейс IDE можно:\\n\\n- установить зависимость\\n\\n- добавить dev-зависимость\\n\\n- удалить пакет\\n\\n- обновить версии\\n\\nПодсказки и анализ зависимостей\\nIDE предоставляют дополнительные возможности.\\nОсновные функции:\\n\\n- подсветка устаревших пакетов\\n\\n- предупреждения о несовместимых версиях\\n\\n- автодополнение при редактировании `package.json`\\n\\nРабота с lock-файлами\\nIDE:\\n\\n- корректно распознают `package-lock.json` или `yarn.lock`\\n\\n- показывают изменения в дереве зависимостей\\n\\n- упрощают код-ревью изменений\\n\\nИнтеграция с внешними инструментами\\nЧасто IDE дополняются:\\n\\n- встроенным терминалом\\n\\n- плагинами для аудита зависимостей\\n\\n- средствами статического анализа\\n\\nВывод\\nСовременные IDE предоставляют удобные инструменты для управления зависимостями, снижая количество ошибок и упрощая сопровождение проектов.",null],[1374,"`key` нужен для того, чтобы Vue мог правильно сопоставлять элементы списка при обновлениях. Он помогает определить, какой элемент изменился, добавился или удалился. Без `key` Vue может переиспользовать DOM-узлы неправильно. Это приводит к визуальным и логическим багам. Поэтому `key` обязателен для динамических списков.","Ключ `key` играет важную роль в алгоритме обновления DOM во Vue.\\nОпределение\\nkey — это уникальный идентификатор элемента списка, который используется Vue для отслеживания его состояния между рендерами.\\nКак Vue использует key\\nПри обновлении списка Vue:\\n\\n- сравнивает старый и новый список\\n\\n- сопоставляет элементы по `key`\\n\\n- минимизирует количество операций с DOM\\n\\nЧто происходит без key\\nЕсли `key` отсутствует:\\n\\n- Vue ориентируется на порядок элементов\\n\\n- DOM-узлы могут переиспользоваться неверно\\n\\n- возможны баги с input, focus и анимациями\\n\\nТребования к key\\nХороший `key`:\\n\\n- уникален в рамках списка\\n\\n- стабилен между рендерами\\n\\n- не зависит от позиции элемента\\n\\nКраткий вывод\\n`key` необходим для корректной и предсказуемой работы списков во Vue и должен использоваться всегда.",null],[1375,"Использование index как `key` приводит к неправильному сопоставлению элементов при изменении массива. При добавлении, удалении или сортировке элементов Vue считает, что элементы просто «переехали». Это может ломать состояние компонентов, input-поля и анимации. Ошибки появляются не сразу, а при изменениях данных. Поэтому index допустим только для статичных списков.","Проблема использования index как `key` связана с тем, что индекс отражает позицию элемента, а не его сущность.\\nОсновная причина\\n`key` должен идентифицировать элемент данных, а не его положение в массиве. Индекс меняется при любых операциях со списком, даже если сами элементы остались теми же.\\nЧто происходит при изменении списка\\nПри использовании index как `key`:\\n\\n- Vue переиспользует DOM-узлы не для тех данных\\n\\n- состояние дочерних компонентов «переезжает»\\n\\n- значения input могут оказаться привязанными к другим элементам\\n\\nКогда index допустим\\nИспользование index возможно, если:\\n\\n- список полностью статичен\\n\\n- элементы никогда не добавляются и не удаляются\\n\\n- порядок элементов не меняется\\n\\nРекомендуемая альтернатива\\nЛучше использовать:\\n\\n- уникальный id из данных\\n\\n- стабильный идентификатор, не зависящий от позиции\\n\\nКраткий вывод\\nIndex как `key` опасен для динамических списков и может приводить к трудноуловимым багам.",null],[1376,"Если передать строку в `key` без `:`, все элементы списка получат одинаковый ключ. Vue не сможет различать элементы между собой. Это ломает алгоритм обновления DOM. В результате возможны визуальные и логические ошибки. Такой `key` фактически бесполезен.","Во Vue наличие `:` перед `key` определяет, как интерпретируется значение.\\nКак Vue читает key\\nСравним два варианта:\\n\\nВ первом случае `key=\\"id\\"` — это обычная строка `\\"id\\"`.\\nВо втором — значение берётся из данных.\\nПоследствия статического key\\nЕсли все элементы имеют одинаковый `key`:\\n\\n- Vue считает их одним и тем же элементом\\n\\n- DOM-узлы переиспользуются некорректно\\n\\n- состояние компонентов путается\\n\\nПочему ошибка не всегда заметна\\nПроблема может проявиться только:\\n\\n- при изменении порядка элементов\\n\\n- при добавлении или удалении элементов\\n\\n- при работе с формами и анимациями\\n\\nКраткий вывод\\n`key` без `:` превращается в строковый литерал и делает список логически некорректным.","<li v-for=\\"item in items\\" key=\\"id\\"></li>\\n<li v-for=\\"item in items\\" :key=\\"item.id\\"></li>"],[1377,"Объектная нотация `:class` позволяет связывать имена классов с условиями. Класс добавляется, если соответствующее выражение истинно. Это делает шаблон наглядным и легко расширяемым. Такой подход предпочтительнее сложных тернарных выражений. Он широко используется в реальных проектах.","Объектная нотация `:class` — самый читаемый и безопасный способ условной стилизации.\\nСинтаксис\\nБазовый пример выглядит так:\\n\\nКак это работает\\nVue:\\n\\n- берёт ключи объекта как имена классов\\n\\n- проверяет значения\\n\\n- добавляет только те классы, где значение `true`\\n\\nИспользование с computed\\nДля сложных условий:\\n\\nПреимущества подхода\\nОбъектная нотация:\\n\\n- улучшает читаемость\\n\\n- легко масштабируется\\n\\n- упрощает поддержку\\n\\nКраткий вывод\\n`:class` с объектной нотацией — стандартный и рекомендуемый способ управления CSS-классами во Vue.","<div :class=\\"{ active: isActive, error: hasError }\\"></div>\\n\\ncomputed: {\\n  classes() {\\n    return {\\n      active: this.isActive,\\n      disabled: this.isDisabled\\n    }\\n  }\\n}\\n\\n<div :class=\\"classes\\"></div>"],[1378,"`:style` позволяет задавать inline-стили на основе данных компонента. Значения могут вычисляться динамически через выражения или computed-свойства. Этот подход полезен для значений, которые сложно выразить через классы. Однако его не рекомендуется использовать для сложной стилизации. Чаще всего `:style` применяется для отдельных свойств.","Директива `:style` используется, когда внешний вид элемента напрямую зависит от данных.\\nОпределение\\n:style — это механизм Vue для динамического задания inline-стилей через JavaScript-объект или массив объектов.\\nБазовый синтаксис\\nПростейший пример:\\n\\nVue применит соответствующее значение в зависимости от состояния данных.\\nОбъектная форма\\nНаиболее распространённый вариант:\\n\\nИспользование computed\\nДля более сложной логики рекомендуется:\\n\\nКогда использовать, а когда нет\\n`:style` уместен, если:\\n\\n- значение вычисляется динамически\\n\\n- стиль зависит от данных\\n\\n- невозможно выразить через классы\\n\\nДля сложных визуальных состояний лучше использовать CSS-классы.\\nКраткий вывод\\n`:style` подходит для точечной динамической стилизации, но не заменяет полноценную работу с CSS.","<div :style=\\"{ color: isError ? \'red\' : \'black\' }\\"></div>\\n\\n<div :style=\\"{ width: size + \'px\', opacity: isVisible ? 1 : 0.5 }\\"></div>\\n\\ncomputed: {\\n  styles() {\\n    return {\\n      backgroundColor: this.isActive ? \'green\' : \'gray\'\\n    }\\n  }\\n}\\n\\n<div :style=\\"styles\\"></div>"],[1379,"В JavaScript отсутствие значения может выражаться по-разному. `null` и `undefined` означают отсутствие значения, а пустая строка — валидное, но пустое значение. Проверка зависит от бизнес-логики. Универсальной проверки не существует. Нужно явно учитывать нужные случаи.","Корректная проверка отсутствия значения зависит от того, какие состояния допустимы в логике приложения.\\nРазные виды «отсутствия»\\nВ JavaScript есть несколько вариантов:\\n\\n- `undefined` — значение не задано\\n\\n- `null` — значение намеренно отсутствует\\n\\n- `\\"\\"` — пустая строка, но значение есть\\n\\nЯвные проверки\\nЧаще всего используются:\\n\\nПроверка на null и undefined\\nДля проверки обоих случаев:\\n\\nЭто корректное исключение, так как `== null` проверяет только `null` и `undefined`.\\nКогда не стоит использовать falsy\\nПроверка:\\n\\nтакже отработает для `0`, `false` и `NaN`, что часто нежелательно.\\nПрактический подход\\nРекомендуется:\\n\\n- явно проверять нужные состояния\\n\\n- не смешивать разные типы отсутствия\\n\\n- учитывать бизнес-смысл значения\\n\\nКраткий вывод\\nОтсутствие значения в JavaScript имеет несколько форм, и корректная проверка должна учитывать конкретный контекст.","value === null\\nvalue === undefined\\nvalue === \'\'\\n\\nvalue == null\\n\\nif (!value)"],[1380,"Falsy-проверка учитывает несколько значений как ложные. Строгое сравнение проверяет конкретное значение и тип. Falsy-проверка проще, но менее точная. Строгое сравнение безопаснее в бизнес-логике. Выбор зависит от задачи.","Разница между falsy-проверкой и строгим сравнением связана с правилами приведения типов в JavaScript.\\nЧто такое falsy\\nК falsy-значениям относятся:\\n\\n- `false`\\n\\n- `0`\\n\\n- `\\"\\"`\\n\\n- `null`\\n\\n- `undefined`\\n\\n- `NaN`\\n\\nПроверка:\\n\\nсработает для всех этих случаев.\\nСтрогое сравнение\\nСтрогое сравнение:\\n\\nпроверяет:\\n\\n- конкретное значение\\n\\n- конкретный тип\\n\\nРиски falsy-проверок\\nFalsy-проверки:\\n\\n- могут скрыть ошибки\\n\\n- ломают логику при допустимых значениях\\n\\n- усложняют отладку\\n\\nКогда что использовать\\nFalsy-проверка уместна:\\n\\n- при простых UI-проверках\\n\\n- когда все falsy равнозначны\\n\\nСтрогое сравнение лучше:\\n\\n- в бизнес-логике\\n\\n- при валидации данных\\n\\n- при работе с формами\\n\\nКраткий вывод\\nFalsy-проверки проще, но менее надёжны, тогда как строгие сравнения дают предсказуемый результат.","if (!value) {}\\n\\nvalue === null"],[1381,"Fallback-контент отображается, когда основные данные отсутствуют или ещё не загружены. Обычно используется условный рендеринг. UI показывает заглушку, текст или альтернативный компонент. Это улучшает UX и предотвращает ошибки. Такой подход используется практически в каждом frontend-приложении.","Отображение fallback-контента — это стандартная практика для устойчивых интерфейсов.\\nОпределение\\nFallback-контент — это альтернативное содержимое, которое показывается пользователю при отсутствии основных данных.\\nБазовый подход\\nЧаще всего используется условный рендеринг:\\n\\nРаспространённые варианты fallback\\nВ реальных проектах применяются:\\n\\n- текстовые сообщения\\n\\n- skeleton-заглушки\\n\\n- пустые состояния (empty state)\\n\\n- альтернативные компоненты\\n\\nГде должна быть логика\\nРекомендуется:\\n\\n- выносить проверки в computed\\n\\n- не усложнять шаблон\\n\\n- разделять логику данных и отображение\\n\\nПрактический эффект\\nFallback-контент:\\n\\n- предотвращает ошибки рендера\\n\\n- делает интерфейс понятнее\\n\\n- улучшает пользовательский опыт\\n\\nКраткий вывод\\nFallback-контент — обязательный элемент надёжного UI и должен обрабатываться явно.","<div v-if=\\"items && items.length\\">\\n  <!-- основной контент -->\\n</div>\\n<div v-else>\\n  Нет данных\\n</div>"],[1382,"Семантическое версионирование — это схема версии вида MAJOR.MINOR.PATCH. MAJOR увеличивается при несовместимых изменениях, MINOR — при добавлении функциональности, PATCH — при исправлении багов. Такая схема позволяет понимать, какие изменения безопасны для обновления зависимостей.","Семантическое версионирование — это стандарт именования версий пакетов, который описывает характер изменений в коде.\\nФормат версии\\nОпределение:\\nВерсия имеет вид\\n`MAJOR.MINOR.PATCH`\\nЧто означает каждая часть\\n\\n- MAJOR\\nНесовместимые изменения API\\n\\n- MINOR\\nНовая функциональность без нарушения совместимости\\n\\n- PATCH\\nИсправления багов\\n\\nПример\\n\\nКак используется на практике\\nВ package.json можно указывать диапазоны:\\n\\nЭто означает:\\n\\n- разрешены обновления MINOR и PATCH\\n\\n- запрещены MAJOR\\n\\nПочему это важно\\n\\n- Управление зависимостями\\n\\n- Предсказуемость обновлений\\n\\n- Контроль совместимости\\n\\nВывод\\nSemVer упрощает управление зависимостями и позволяет безопасно обновлять библиотеки.","1.4.2 → 1.5.0  (добавили новую возможность)\\n1.5.0 → 2.0.0  (сломали старый API)\\n\\neact\\": \\"^18.2.0\\""],[1383,"`peerDependencies` — это зависимости, которые библиотека ожидает получить из проекта, а не устанавливает сама. Обычно они используются для библиотек, работающих поверх другой библиотеки, например React-плагинов. Это помогает избежать установки нескольких версий одной и той же зависимости.","`peerDependencies` — это способ указать, что библиотека должна работать с уже установленной зависимостью в проекте.\\nЗачем это нужно\\nОсновная задача — избежать ситуации, когда:\\n\\n- библиотека использует одну версию React\\n\\n- приложение — другую\\n\\nЭто может привести к ошибкам, например нарушению работы хуков.\\nКак это выглядит\\n\\nЭто означает:\\n\\n- библиотека требует React\\n\\n- но не устанавливает его автоматически\\n\\nКогда используется\\n\\n- UI-библиотеки\\n\\n- плагины\\n\\n- middleware\\n\\nОтличие от dependencies\\n\\n- `dependencies` устанавливаются автоматически\\n\\n- `peerDependencies` — нет, их должен установить разработчик\\n\\nВывод\\n`peerDependencies` применяются, когда библиотека должна использовать одну и ту же версию зависимости вместе с приложением.","{\\n  \\"peerDependencies\\": {\\n    eact\\": \\"^18.0.0\\"\\n  }\\n}"],[1384,"На практике часто используются стрелочные функции, деструктуризация, spread/rest, optional chaining, nullish coalescing и async/await. Эти возможности упрощают код и делают его короче и читаемее. Большинство современных браузеров и сборщиков поддерживают их.","Современные стандарты JavaScript (ES6+) добавили множество возможностей, которые активно применяются в frontend-разработке.\\nНаиболее используемые возможности\\n\\n- Стрелочные функции\\n\\nИспользуются для краткого синтаксиса и сохранения `this`.\\n\\n- Деструктуризация\\n\\nУпрощает доступ к данным.\\n\\n- Spread и Rest\\n\\nИспользуется для копирования и объединения данных.\\n\\n- Optional chaining\\n\\nПозволяет безопасно обращаться к вложенным свойствам.\\n\\n- Async/await\\n\\nУпрощает работу с асинхронным кодом.\\nПочему это важно\\n\\n- Код становится короче\\n\\n- Меньше ошибок\\n\\n- Лучше читаемость\\n\\nВывод\\nСовременные возможности JavaScript используются повсеместно, так как упрощают синтаксис и повышают читаемость кода.","const sum = (a, b) => a + b;\\n\\nconst { name } = user;\\n\\nconst newArr = [...arr];\\n\\nuser?.profile?.email\\n\\nconst data = await fetch(url);"],[1385,"События в DOM проходят три фазы: capturing, target и bubbling. В фазе capturing событие сначала проходит сверху вниз по дереву DOM. Чтобы обработчик сработал на этой фазе, нужно передать параметр `capture: true` в `addEventListener`.","Система событий в браузере основана на распространении события по дереву DOM.\\nФазы события\\n\\n- Capturing phase\\nСобытие идет от `window` к целевому элементу.\\n\\n- Target phase\\nСрабатывает обработчик целевого элемента.\\n\\n- Bubbling phase\\nСобытие поднимается обратно вверх.\\n\\nКак подписаться на capturing\\n\\nКогда используется capturing\\n\\n- глобальные обработчики\\n\\n- перехват событий до bubbling\\n\\n- сложные UI-компоненты\\n\\nПочему чаще используют bubbling\\n\\n- проще логика\\n\\n- меньше неожиданного поведения\\n\\nВывод\\nCapturing — это первая фаза распространения события, которая используется реже, но полезна для перехвата событий до их обработки другими элементами.","element.addEventListener(\\"click\\", handler, { capture: true });"],[1386,"Подписка на события выполняется через `addEventListener`. В него передается тип события, обработчик и объект параметров. Можно указать параметры `capture`, `once`, `passive` и другие, которые управляют поведением обработчика.","В браузере события обрабатываются через систему слушателей событий.\\nБазовый синтаксис\\n\\nОсновные параметры\\n\\n- capture\\nОбработчик срабатывает в фазе перехвата.\\n\\n- once\\nОбработчик выполнится один раз.\\n\\n- passive\\nСообщает браузеру, что обработчик не вызовет `preventDefault()`.\\n\\nЭто важно для производительности, например при scroll.\\nОтписка от события\\n\\nКогда важно использовать параметры\\n\\n- scroll и touch-события\\n\\n- оптимизация производительности\\n\\n- предотвращение утечек памяти\\n\\nВывод\\nГибкость `addEventListener` позволяет точно контролировать поведение обработчиков и производительность.","element.addEventListener(\\"click\\", handler);\\n\\n{ capture: true }\\n\\n{ once: true }\\n\\n{ passive: true }\\n\\nelement.removeEventListener(\\"click\\", handler);"],[1387,"Метод `sort()` по умолчанию сортирует элементы как строки. Поэтому числа сравниваются лексикографически, а не по значению. Например, `10` может оказаться перед `2`. Чтобы сортировать числа правильно, нужно передать компаратор.","Метод `Array.sort()` без аргументов приводит элементы к строке и сравнивает их посимвольно.\\nПример проблемы\\n\\nПричина:\\n\\n- сравниваются строки `\\"10\\"` и `\\"2\\"`\\n\\n- символ `\\"1\\"` меньше `\\"2\\"`\\n\\nПравильная сортировка чисел\\n\\nКак работает компаратор\\n\\n- возвращает отрицательное число — `a` раньше `b`\\n\\n- положительное — `b` раньше `a`\\n\\n- 0 — порядок не меняется\\n\\nКогда это важно\\n\\n- сортировка чисел\\n\\n- сортировка дат\\n\\n- сложные структуры\\n\\nВывод\\nБез компаратора `sort()` работает как строковая сортировка, поэтому для чисел всегда нужно передавать функцию сравнения.","[1, 2, 10].sort();\\n// результат: [1, 10, 2]\\n\\n[1, 2, 10].sort((a, b) => a - b);"],[1388,"Простейший алгоритм сжатия строки — это run-length encoding, при котором одинаковые символы заменяются символом и количеством повторений. Например, `aaabb` превращается в `a3b2`. Такой алгоритм выполняется за O(n), так как строка проходит один раз.","Один из самых простых способов сжатия строки — алгоритм RLE (Run-Length Encoding).\\nИдея алгоритма\\nОпределение:\\nRLE — это метод сжатия, при котором последовательности одинаковых символов заменяются символом и количеством повторений.\\nПример\\n\\nПример реализации\\n\\nОценка сложности\\n\\n- Временная сложность: O(n)\\n\\n- Пространственная сложность: O(n)\\n\\nПричина:\\n\\n- строка проходит один раз\\n\\n- результат хранится отдельно\\n\\nГде применяется\\n\\n- простые форматы сжатия\\n\\n- кодирование данных\\n\\n- обработка логов\\n\\nВывод\\nRLE — простой алгоритм сжатия, который удобен для задач с повторяющимися символами и хорошо демонстрирует оценку сложности.","aaabcccc → a3b1c4\\n\\nfunction compress(str) {\\n  let result = \\"\\";\\n  let count = 1;\\n\\n  for (let i = 1; i <= str.length; i++) {\\n    if (str[i] === str[i - 1]) {\\n      count++;\\n    } else {\\n      result += str[i - 1] + count;\\n      count = 1;\\n    }\\n  }\\n  return result;\\n}"],[1389,"Big-O — это способ оценить, как растет время выполнения или потребление памяти алгоритма при увеличении входных данных. Например, O(n) означает линейный рост, а O(n²) — квадратичный. Это позволяет сравнивать алгоритмы независимо от конкретного железа или языка.","Big-O используется для оценки эффективности алгоритмов, чтобы понимать, как они будут работать на больших объемах данных.\\nОсновная идея\\nОпределение:\\nBig-O — это асимптотическая оценка роста времени или памяти алгоритма при увеличении размера входных данных.\\nНаиболее распространенные сложности\\n\\n- O(1) — константная\\nДоступ к элементу массива по индексу.\\n\\n- O(n) — линейная\\nОдин проход по массиву.\\n\\n- O(n²) — квадратичная\\nДва вложенных цикла.\\n\\nПример\\n\\nПочему это важно\\n\\n- выбор алгоритма\\n\\n- оптимизация производительности\\n\\n- проектирование систем\\n\\nЧто не учитывает Big-O\\n\\n- константы\\n\\n- особенности реализации\\n\\n- кэш процессора\\n\\nВывод\\nBig-O помогает прогнозировать масштабируемость алгоритмов и выбирать более эффективные решения.","for (let i = 0; i < arr.length; i++) {\\n  // операция O(n)\\n}"],[1390,"Function declaration объявляется через ключевое слово `function` и поднимается (hoisting). Arrow function записывается через стрелочный синтаксис и не имеет собственного `this`. Также arrow function нельзя использовать как конструктор и у нее нет `arguments`.","В JavaScript существует несколько способов объявления функций, но чаще всего сравнивают function declaration и arrow function.\\nFunction declaration\\n\\nОсобенности:\\n\\n- поднимается (hoisting)\\n\\n- имеет собственный `this`\\n\\n- можно использовать как конструктор\\n\\nArrow function\\n\\nОсобенности:\\n\\n- не имеет собственного `this`\\n\\n- не поднимается как declaration\\n\\n- нельзя использовать с `new`\\n\\nГлавное отличие this\\n\\nArrow function берет `this` из внешнего контекста.\\nКогда что использовать\\n\\n- Arrow function — колбэки, обработчики, функциональные компоненты\\n\\n- Function declaration — методы, конструкторы, API\\n\\nВывод\\nArrow function удобны для коротких функций и колбэков, а function declaration — для объявлений, требующих hoisting или собственного контекста.","function sum(a, b) {\\n  return a + b;\\n}\\n\\nconst sum = (a, b) => a + b;\\n\\nconst obj = {\\n  value: 10,\\n  method() {\\n    setTimeout(() => {\\n      console.log(this.value);\\n    });\\n  }\\n};"],[1391,"Обычный тег `<script>` блокирует парсинг HTML, пока файл не загрузится и не выполнится. Атрибут `defer` позволяет продолжить парсинг и выполнить скрипт после построения DOM. Атрибут `async` загружает и выполняет скрипт независимо от DOM. Выбор режима влияет на скорость загрузки и порядок выполнения.","Теги script напрямую влияют на то, как браузер строит DOM и выполняет JavaScript.\\n1) Поведение обычного script\\nКогда браузер встречает:\\n\\nПроисходит:\\n\\n- Остановка парсинга HTML.\\n\\n- Загрузка файла.\\n\\n- Выполнение скрипта.\\n\\n- Продолжение парсинга.\\n\\nЭто называется parser blocking.\\n2) Атрибут defer\\n\\nОсобенности:\\n\\n- HTML продолжает парситься.\\n\\n- Скрипт выполняется после построения DOM.\\n\\n- Порядок выполнения сохраняется.\\n\\nИспользуется для:\\n\\n- основного кода приложения\\n\\n- инициализации интерфейса\\n\\n3) Атрибут async\\n\\nОсобенности:\\n\\n- Загружается параллельно.\\n\\n- Выполняется сразу после загрузки.\\n\\n- Порядок выполнения не гарантируется.\\n\\nИспользуется для:\\n\\n- аналитики\\n\\n- сторонних виджетов\\n\\n4) Почему это важно\\nНеправильное подключение:\\n\\n- Увеличивает время до первой отрисовки.\\n\\n- Замедляет построение DOM.\\n\\n- Ухудшает Core Web Vitals.\\n\\nВывод: обычный script блокирует парсинг HTML, defer откладывает выполнение, async выполняется независимо и быстрее, но без гарантии порядка.","<script src=\\"app.js\\"><\/script>\\n\\n<script src=\\"app.js\\" defer><\/script>\\n\\n<script src=\\"analytics.js\\" async><\/script>"],[1392,"Задачи попадают в очередь microtask после выполнения Promise, `queueMicrotask` или `MutationObserver`. Они выполняются сразу после завершения текущего стека вызовов и перед следующей macrotask. Поэтому microtask имеют более высокий приоритет. Это влияет на порядок выполнения кода и отрисовку.","Microtask — часть механизма event loop, который определяет порядок выполнения асинхронного кода.\\n1) Когда создаются microtask\\nMicrotask добавляются при:\\n\\n- Выполнении `Promise.then`, `catch`, `finally`.\\n\\n- Вызове `queueMicrotask`.\\n\\n- Использовании `MutationObserver`.\\n\\nПример:\\n\\n2) Когда они выполняются\\nОпределение: Microtask queue — очередь задач, которая выполняется сразу после завершения текущего стека вызовов, но до следующей macrotask.\\nПорядок:\\n\\n- Выполняется текущий код.\\n\\n- Выполняются все microtask.\\n\\n- Затем следующая macrotask.\\n\\n3) Отличие от macrotask\\nMacrotask:\\n\\n- setTimeout\\n\\n- setInterval\\n\\n- события DOM\\n\\nMicrotask:\\n\\n- Promise\\n\\n- queueMicrotask\\n\\nПример:\\n\\nРезультат:\\n\\n4) Почему это важно для React и браузера\\n\\n- Microtask могут выполняться перед отрисовкой.\\n\\n- Большое количество microtask может задержать repaint.\\n\\n- Это влияет на производительность.\\n\\nВывод: microtask добавляются при работе Promise и подобных механизмов и выполняются сразу после текущего кода, раньше macrotask.","Promise.resolve().then(() => {\\n  console.log(\\"microtask\\");\\n});\\n\\nsetTimeout(() => console.log(\\"macrotask\\"));\\nPromise.resolve().then(() => console.log(\\"microtask\\"));\\n\\nmicrotask\\nmacrotask"],[1393,"Переменные внутри функции создаются на этапе подготовки контекста выполнения, ещё до выполнения кода функции. Движок JavaScript сначала создаёт переменные и функции, а затем выполняет код построчно. При этом `var` и функции инициализируются иначе, чем `let` и `const`. Последние находятся в так называемой временной мёртвой зоне до момента объявления.","Создание переменных происходит не в момент выполнения строки, а раньше — при создании контекста выполнения функции.\\n1) Две фазы выполнения функции\\nКогда вызывается функция, движок проходит два этапа:\\n\\n- Creation phase (создание контекста):\\n\\n- создаются переменные\\n\\n- создаются функции\\n\\n- формируется scope\\n\\n- Execution phase:\\n\\n- код выполняется построчно\\n\\n2) Что происходит с разными типами объявлений\\nОпределение: Hoisting — механизм, при котором объявления переменных и функций обрабатываются до выполнения кода.\\nПоведение:\\n\\n- `var`\\n\\n- создаётся и инициализируется значением `undefined`\\n\\n- `let` и `const`\\n\\n- создаются, но не инициализируются\\n\\n- доступ запрещён до строки объявления (TDZ)\\n\\n- function declaration\\n\\n- создаётся полностью\\n\\nПример:\\n\\n3) Временная мёртвая зона\\nОпределение: Temporal Dead Zone (TDZ) — область кода от начала блока до объявления переменной `let` или `const`, где доступ к ней запрещён.\\nПример:\\n\\n4) Почему это важно\\n\\n- Объясняет порядок выполнения кода.\\n\\n- Помогает избегать ошибок с undefined.\\n\\n- Позволяет правильно проектировать область видимости.\\n\\nВывод: переменные создаются на этапе создания контекста выполнения, но инициализируются по-разному в зависимости от типа объявления.","console.log(a); // undefined\\nvar a = 10;\\n\\nconsole.log(x); // ReferenceError\\nlet x = 5;"],[1394,"Чистая функция должна зависеть только от своих аргументов и не изменять внешнее состояние. Если функция использует внешнюю переменную, результат может измениться без изменения аргументов. Это усложняет тестирование и делает код менее предсказуемым. Поэтому в функциональном стиле стараются избегать внешних зависимостей.","Использование внешних переменных связано с понятием чистых функций.\\n1) Что такое чистая функция\\nОпределение: Pure function — функция, которая:\\n\\n- Возвращает одинаковый результат при одинаковых аргументах.\\n\\n- Не имеет побочных эффектов.\\n\\nПример чистой функции:\\n\\n2) Что происходит при использовании внешних переменных\\nПример:\\n\\nПроблемы:\\n\\n- Результат зависит не только от аргументов.\\n\\n- Внешнее состояние может измениться.\\n\\n- Поведение становится менее предсказуемым.\\n\\n3) Почему это плохо на практике\\n\\n- Сложнее тестировать.\\n\\n- Сложнее переиспользовать.\\n\\n- Повышается риск скрытых багов.\\n\\n4) Когда это допустимо\\nИногда это нормально:\\n\\n- Конфигурация.\\n\\n- Константы.\\n\\n- Dependency injection.\\n\\nВывод: внешние переменные делают функцию зависимой от контекста, поэтому чистые функции стараются использовать только аргументы.","function sum(a, b) {\\n  return a + b;\\n}\\n\\nlet tax = 0.2;\\n\\nfunction calc(price) {\\n  return price * tax;\\n}"],[1395,"Инкрементирующую функцию можно сделать через замыкание, сохранив переменную во внешней функции. Внутренняя функция будет иметь доступ к этой переменной и изменять её при каждом вызове. Значение будет сохраняться между вызовами. Это один из классических примеров использования замыканий.","Замыкания позволяют функции запоминать переменные из внешней области видимости.\\n1) Что такое замыкание\\nОпределение: Closure — функция, которая имеет доступ к переменным из внешнего scope даже после завершения выполнения внешней функции.\\n2) Реализация инкремента\\nПример:\\n\\n3) Почему это работает\\n\\n- Внутренняя функция хранит ссылку на переменную `count`.\\n\\n- Контекст не уничтожается, пока существует ссылка.\\n\\n- Значение сохраняется между вызовами.\\n\\n4) Где применяется на практике\\n\\n- Счётчики.\\n\\n- Кэширование.\\n\\n- Инкапсуляция состояния.\\n\\nВывод: замыкание позволяет хранить состояние внутри функции без глобальных переменных и без передачи параметров.","function createCounter() {\\n  let count = 0;\\n\\n  return function () {\\n    count++;\\n    return count;\\n  };\\n}\\n\\nconst counter = createCounter();\\n\\ncounter(); // 1\\ncounter(); // 2"],[1396,"Переменные `var` в глобальной области становятся свойствами `window`, а `let` и `const` — нет. Это связано с тем, что `let` и `const` создаются в глобальном лексическом окружении, а не как свойства объекта. Они доступны в глобальной области видимости, но не через `window`. Это сделано для более безопасной и предсказуемой работы со scope.","Важно различать глобальную область видимости и глобальный объект — это не одно и то же.\\n1) Как работает var\\nПри объявлении:\\n\\nПроисходит:\\n\\n- Переменная добавляется в глобальный scope.\\n\\n- Она становится свойством `window`.\\n\\nПроверка:\\n\\n2) Как работают let и const\\nПри объявлении:\\n\\nПроисходит:\\n\\n- Переменные создаются в глобальном лексическом окружении.\\n\\n- Они не добавляются в объект `window`.\\n\\nПроверка:\\n\\n3) Почему так сделано\\nОсновные причины:\\n\\n- Избежать случайного загрязнения глобального объекта.\\n\\n- Улучшить изоляцию кода.\\n\\n- Сделать поведение более предсказуемым.\\n\\n4) Практический вывод\\n\\n- Не стоит полагаться на доступ к переменным через `window`.\\n\\n- Лучше явно экспортировать значения, если они нужны глобально.\\n\\nВывод: `let` и `const` создают переменные в глобальном scope, но не в глобальном объекте, поэтому они не появляются в `window`.","var a = 10;\\n\\nconsole.log(window.a); // 10\\n\\nlet b = 20;\\nconst c = 30;\\n\\nconsole.log(window.b); // undefined"],[1397,"В JavaScript значение по динамическому ключу получают через квадратные скобки. Внутрь скобок передается переменная, содержащая имя свойства. Точечная нотация для этого не подходит, потому что она работает только со статическими именами. Такой подход часто используется при работе с API и формами.","Когда имя свойства заранее неизвестно и хранится в переменной, используется доступ через квадратные скобки.\\nОпределение:\\nДинамический ключ (`dynamic key`) — это имя свойства объекта, которое хранится в переменной и определяется во время выполнения программы.\\nПример:\\n\\nПочему нельзя использовать точку\\nТочечная запись не использует значение переменной, а воспринимает текст буквально.\\n\\nГде применяется\\n\\n- Работа с формами, где имя поля приходит динамически.\\n\\n- Обработка данных API.\\n\\n- Универсальные функции для работы с объектами.\\n\\nПример функции\\n\\nВывод\\nДоступ через квадратные скобки применяется всегда, когда имя свойства определяется во время выполнения программы.","const user = {\\n  name: \\"Ivan\\",\\n  age: 25\\n};\\n\\nconst key = \\name\\";\\n\\nconsole.log(user[key]); // Ivan\\n\\nuser.key // будет искать свойство \\"key\\"\\n\\nfunction getValue(obj, field) {\\n  return obj[field];\\n}"],[1398,"LocalStorage — это встроенное хранилище браузера для сохранения данных в формате ключ-значение. Данные сохраняются между перезагрузками и закрытием браузера. Значения хранятся только как строки. Обычно используется для настроек, токенов и небольших кэшей.","LocalStorage является частью Web Storage API и используется для хранения данных на стороне клиента.\\nОпределение:\\nLocalStorage — это механизм постоянного хранения данных в браузере в формате `key-value`, доступный через объект `localStorage`.\\nОсновные операции\\n\\nОсобенности\\n\\n- Данные сохраняются после перезагрузки страницы.\\n\\n- Доступ возможен только в пределах одного домена.\\n\\n- Значения хранятся в строковом виде.\\n\\nПример хранения объекта\\n\\nКогда используется\\n\\n- Хранение токенов авторизации.\\n\\n- Сохранение настроек пользователя.\\n\\n- Кэширование простых данных интерфейса.\\n\\nВывод\\nLocalStorage подходит для хранения небольших данных, которые должны сохраняться между сессиями браузера.","localStorage.setItem(  oken\\", \\"123\\");\\nlocalStorage.getItem(  oken\\");\\nlocalStorage.removeItem(  oken\\");\\nlocalStorage.clear();\\n\\nconst user = { name: \\"Ivan\\" };\\n\\nlocalStorage.setItem(\\"user\\", JSON.stringify(user));\\n\\nconst parsed = JSON.parse(localStorage.getItem(\\"user\\"));"],[1399,"Метод `map()` создает новый массив, применяя функцию к каждому элементу исходного массива. Исходный массив не изменяется. Количество элементов сохраняется. Метод используется для преобразования данных.","Метод `map()` — один из основных инструментов обработки массивов в JavaScript.\\nОпределение:\\n`map()` — это метод массива, который возвращает новый массив, сформированный результатами выполнения функции для каждого элемента исходного массива.\\nПример\\n\\nКак работает\\n\\n- Перебирает каждый элемент массива.\\n\\n- Вызывает функцию-колбэк.\\n\\n- Сохраняет результат в новый массив.\\n\\nПример с объектами\\n\\nГде применяется\\n\\n- Подготовка данных для UI.\\n\\n- Формирование списков в React.\\n\\n- Преобразование ответа API.\\n\\nПример в React\\n\\nВывод\\n`map()` используется, когда требуется преобразовать массив и получить новый результат без изменения исходных данных.","const numbers = [1, 2, 3];\\n\\nconst doubled = numbers.map(n => n * 2);\\n\\nconsole.log(doubled); // [2, 4, 6]\\n\\nconst users = [\\n  { name: \\"Ivan\\" },\\n  { name: \\"Anna\\" }\\n];\\n\\nconst names = users.map(user => user.name);\\n\\nitems.map(item => (\\n  <li key={item.id}>{item.name}</li>\\n));"],[1400,"Метод `forEach()` перебирает массив и выполняет функцию для каждого элемента, но не возвращает новый массив. Чтобы сформировать новый массив, его нужно создать заранее и вручную добавлять элементы. Это делает код более многословным, чем при использовании `map()`. Поэтому `forEach()` обычно применяют для побочных действий, а не преобразования массива.","Метод `forEach()` используется для последовательного выполнения функции над каждым элементом массива.\\nОпределение:\\n`forEach()` — это метод массива, который выполняет переданную функцию для каждого элемента, но не возвращает новый массив.\\nПример создания нового массива\\n\\nКак работает\\n\\n- Перебирает элементы массива по порядку.\\n\\n- Вызывает функцию-колбэк.\\n\\n- Не формирует результирующий массив автоматически.\\n\\nКогда используется\\n\\n- Логирование и отладка.\\n\\n- Изменение внешних переменных.\\n\\n- Выполнение побочных действий.\\n\\nВывод\\n`forEach()` подходит для действий над элементами массива, но если требуется новый массив, чаще используют `map()`.","const numbers = [1, 2, 3];\\nconst result = [];\\n\\nnumbers.forEach(n => {\\n  result.push(n * 2);\\n});\\n\\nconsole.log(result); // [2, 4, 6]"]]');export{e as default};